enum PlanType { basico, profissional, enterprise }

extension PlanTypeText on PlanType {
  String get label {
    switch (this) {
      case PlanType.basico:
        return 'Básico';
      case PlanType.profissional:
        return 'Profissional';
      case PlanType.enterprise:
        return 'Enterprise';
    }
  }
}

class PointReading {
  final String point;
  final double ph;
  final double turbidity;
  final double tds;

  const PointReading({
    required this.point,
    required this.ph,
    required this.turbidity,
    required this.tds,
  });
}

class HistoryRecord {
  final DateTime date;
  final String point;
  final double ph;
  final double turbidity;
  final double tds;
  final String status;

  const HistoryRecord({
    required this.date,
    required this.point,
    required this.ph,
    required this.turbidity,
    required this.tds,
    required this.status,
  });
}

/// Leitura realizada no fundo do reservatório após a movimentação controlada
/// da água pela bomba. Usa os mesmos três parâmetros do monitoramento: pH,
/// turbidez e TDS.
class BottomConditionRecord {
  final DateTime date;
  final double ph;
  final double turbidity;
  final double tds;
  final String status;

  const BottomConditionRecord({
    required this.date,
    required this.ph,
    required this.turbidity,
    required this.tds,
    required this.status,
  });
}

class DeletedAnalysisRecord {
  final DateTime date;
  final String reason;
  final DateTime deletedAt;
  final String deletedBy;
  final String verificationCode;

  const DeletedAnalysisRecord({
    required this.date,
    required this.reason,
    required this.deletedAt,
    required this.deletedBy,
    required this.verificationCode,
  });
}

String digitalVerificationCode(DateTime date, String reason) {
  final raw = '${date.millisecondsSinceEpoch}|$reason|AQUA';
  var hash = 17;
  for (final c in raw.codeUnits) {
    hash = (hash * 31 + c) & 0x7fffffff;
  }
  return 'AQUA-${date.year}${date.month.toString().padLeft(2, '0')}${date.day.toString().padLeft(2, '0')}-${hash.toRadixString(16).toUpperCase().padLeft(8, '0')}';
}

class Reservoir {
  final String id;
  String name;
  String location;
  int liters;
  String type;
  double ph;
  double turbidity;
  double tds;
  String status;
  double latitude;
  double longitude;
  DateTime lastUpdate;
  List<PointReading> points;
  List<HistoryRecord> history;
  List<BottomConditionRecord> bottomHistory;
  List<DeletedAnalysisRecord> deletedAnalyses;

  Reservoir({
    required this.id,
    required this.name,
    required this.location,
    required this.liters,
    required this.type,
    required this.ph,
    required this.turbidity,
    required this.tds,
    required this.status,
    required this.latitude,
    required this.longitude,
    required this.lastUpdate,
    List<PointReading>? points,
    List<HistoryRecord>? history,
    List<BottomConditionRecord>? bottomHistory,
    List<DeletedAnalysisRecord>? deletedAnalyses,
    bool seedDemoHistory = true,
  })  : points = points ??
            [
              PointReading(
                point: 'P1',
                ph: ph + .04,
                turbidity: math.max(.1, turbidity - .25),
                tds: math.max(0, tds - 10),
              ),
              PointReading(
                point: 'P2',
                ph: ph,
                turbidity: turbidity,
                tds: tds,
              ),
              PointReading(
                point: 'P3',
                ph: ph - .06,
                turbidity: turbidity + .38,
                tds: tds + 18,
              ),
            ],
        history = history ??
            (seedDemoHistory
                ? List.generate(
              8,
              (i) {
                final d = DateTime.now().subtract(Duration(days: 7 - i));
                final t = math.max(
                  .35,
                  turbidity + math.sin(i * .9) * .65,
                );
                return HistoryRecord(
                  date: d,
                  point: i.isEven ? 'P2' : 'P3',
                  ph: ph + math.sin(i * .7) * .08,
                  turbidity: t,
                  tds: tds + math.sin(i * .6) * 22,
                  status: statusForTurbidity(t),
                );
              },
            )
                : <HistoryRecord>[]),
        bottomHistory = bottomHistory ??
            (seedDemoHistory
                ? List.generate(
                    8,
                    (i) {
                      final d = DateTime.now().subtract(Duration(days: 7 - i));
                      final t = math.max(
                        .35,
                        turbidity + .85 + math.sin(i * .9).abs() * .55,
                      );
                      return BottomConditionRecord(
                        date: d,
                        ph: ph - .08 + math.sin(i * .7) * .05,
                        turbidity: t,
                        tds: tds + 30 + math.sin(i * .6).abs() * 18,
                        status: statusForTurbidity(t),
                      );
                    },
                  )
                : <BottomConditionRecord>[]),
        deletedAnalyses = deletedAnalyses ?? <DeletedAnalysisRecord>[];

  PointReading readingFor(String point) {
    return points.firstWhere(
      (p) => p.point == point,
      orElse: () => points.first,
    );
  }
}

PointReading bottomBeforeReading(Reservoir r, BottomConditionRecord b) {
  final sameDay = r.history.where((h) =>
      h.point == 'P3' &&
      h.date.year == b.date.year &&
      h.date.month == b.date.month &&
      h.date.day == b.date.day &&
      !h.date.isAfter(b.date)).toList()
    ..sort((a, c) => c.date.compareTo(a.date));
  if (sameDay.isNotEmpty) {
    final h = sameDay.first;
    return PointReading(point: 'P3', ph: h.ph, turbidity: h.turbidity, tds: h.tds);
  }
  return r.readingFor('P3');
}

String statusForTurbidity(double value) {
  if (value >= 4.0) return 'Suja';
  if (value >= 2.0) return 'Atenção';
  return 'Limpa';
}

class Company {
  final String id;
  String name;
  String contact;
  String phone;
  String location;
  PlanType plan;
  String logoUrl;
  Color color;
  List<String> contacts;
  final List<Reservoir> reservoirs;
  String clientName;
  String clientPhone;
  String clientEmail;
  List<String> clientCollaborators;

  Company({
    required this.id,
    required this.name,
    required this.contact,
    required this.phone,
    required this.location,
    required this.plan,
    required this.reservoirs,
    this.logoUrl = '',
    this.color = const Color(0xFF087E8B),
    List<String>? contacts,
    this.clientName = '',
    this.clientPhone = '',
    this.clientEmail = '',
    List<String>? clientCollaborators,
  })  : contacts = contacts ?? [],
        clientCollaborators = clientCollaborators ?? [];
}

