Company? companyById(String id) {
  for (final c in companies) {
    if (c.id == id) return c;
  }
  return null;
}

Reservoir? reservoirById(String companyId, String reservoirId) {
  final company = companyById(companyId);
  if (company == null) return null;
  for (final r in company.reservoirs) {
    if (r.id == reservoirId) return r;
  }
  return null;
}

