class ClientHomePage extends StatefulWidget {
  final Company company;
  const ClientHomePage({super.key, required this.company});

  @override
  State<ClientHomePage> createState() => _ClientHomePageState();
}

class _ClientHomePageState extends State<ClientHomePage> {
  int selected = 0;
  Reservoir? focused;
  Reservoir? analysisReservoir;
  String? analysisPoint;
  String? analysisParameter;
  int analysisSection = 0;
  Reservoir? monitorReservoir;
  String? monitorPoint;
  String? monitorParameter;

  @override
  void initState() {
    super.initState();
    if (widget.company.reservoirs.isNotEmpty) focused = widget.company.reservoirs.first;
  }

  @override
  Widget build(BuildContext context) {
    final pages = [
      ClientMonitorHome(
        company: widget.company,
        initialReservoir: monitorReservoir,
        initialPoint: monitorPoint,
        initialParameter: monitorParameter,
        onOpenAnalysis: (reservoir, point, parameter) {
          setState(() {
            analysisReservoir = reservoir;
            analysisPoint = point;
            analysisParameter = parameter;
            analysisSection = 0;
            selected = 1;
          });
        },
        onOpenBottomConditions: (reservoir) {
          setState(() {
            analysisReservoir = reservoir;
            analysisPoint = 'Todos';
            analysisParameter = 'Todos';
            analysisSection = 1;
            selected = 1;
          });
        },
      ),
      ClientAnalysesReportsPage(
        key: ValueKey('analyses-${analysisReservoir?.id}-${analysisPoint ?? 'Todos'}-${analysisParameter ?? 'Todos'}'),
        company: widget.company,
        initialReservoir: analysisReservoir,
        initialPoint: analysisPoint,
        initialParameter: analysisParameter,
        initialSection: analysisSection,
      ),
      ClientMapPage(
        company: widget.company,
        initialReservoir: focused,
        onReservoirSelected: (r) => setState(() => focused = r),
        onOpenMonitoring: (r) {
          setState(() {
            focused = r;
            monitorReservoir = r;
            // Ao vir do mapa, somente a caixa é definida.
            // Ponto e parâmetro não são impostos pela seleção do mapa.
            monitorPoint = null;
            monitorParameter = null;
            selected = 0;
          });
        },
      ),
      ClientMorePage(company: widget.company),
    ];
    return Scaffold(
      appBar: AppBar(
        titleSpacing: 12,
        title: InkWell(
          borderRadius: BorderRadius.circular(14),
          onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ClientCompanyProfilePage(company: widget.company))).then((_) => setState(() {})),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            CompanyAvatar(company: widget.company, radius: 17),
            const SizedBox(width: 10),
            Flexible(child: Text(widget.company.name, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w700))),
            const SizedBox(width: 4),
            const Icon(Icons.keyboard_arrow_down_rounded, size: 19),
          ]),
        ),
        actions: [
          NotificationBell(
            companyId: widget.company.id,
            onOpenNotification: (notification) => Navigator.push(
              context,
              MaterialPageRoute(
                builder: (_) => ClientMessages(
                  company: widget.company,
                  initialNotification: notification,
                  onVerify: (reservoir, point, parameter) {
                    Navigator.pop(context);
                    setState(() {
                      monitorReservoir = reservoir;
                      monitorPoint = point;
                      monitorParameter = parameter;
                      selected = 0;
                    });
                  },
                ),
              ),
            ),
          ),
          IconButton(tooltip: 'Perfil', onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ClientCompanyProfilePage(company: widget.company))), icon: const Icon(Icons.person_outline_rounded)),
        ],
      ),
      body: AnimatedSwitcher(duration: const Duration(milliseconds: 220), child: pages[selected]),
      bottomNavigationBar: SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 0, 10, 8),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(24),
            child: NavigationBar(
              selectedIndex: selected,
              onDestinationSelected: (v) => setState(() => selected = v),
              labelBehavior: NavigationDestinationLabelBehavior.alwaysShow,
              destinations: const [
          NavigationDestination(icon: Icon(Icons.water_drop_outlined), selectedIcon: Icon(Icons.water_drop_rounded), label: 'Monitoramento'),
          NavigationDestination(icon: Icon(Icons.analytics_outlined), selectedIcon: Icon(Icons.analytics_rounded), label: 'Análises'),
          NavigationDestination(icon: Icon(Icons.map_outlined), selectedIcon: Icon(Icons.map_rounded), label: 'Mapa'),
          NavigationDestination(icon: Icon(Icons.more_horiz_rounded), selectedIcon: Icon(Icons.more_horiz_rounded), label: 'Mais'),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class ClientMapPage extends StatefulWidget {
  final Company company;
  final Reservoir? initialReservoir;
  final ValueChanged<Reservoir>? onReservoirSelected;
  final ValueChanged<Reservoir>? onOpenMonitoring;

  const ClientMapPage({
    super.key,
    required this.company,
    this.initialReservoir,
    this.onReservoirSelected,
    this.onOpenMonitoring,
  });

  @override
  State<ClientMapPage> createState() => _ClientMapPageState();
}

class _ClientMapPageState extends State<ClientMapPage> {
  Reservoir? selected;
  bool _mapInteracting = false;
  int _recenterToken = 0;

  @override
  void initState() {
    super.initState();
    selected = widget.initialReservoir ??
        (widget.company.reservoirs.isNotEmpty ? widget.company.reservoirs.first : null);
  }

  void selectReservoir(Reservoir r) {
    setState(() {
      selected = r;
      _recenterToken++;
    });
    widget.onReservoirSelected?.call(r);
  }

  void selectReservoirFromMap(Reservoir r) {
    selectReservoir(r);
    widget.onOpenMonitoring?.call(r);
  }

  @override
  Widget build(BuildContext context) {
    final reservoirs = widget.company.reservoirs;

    if (reservoirs.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(30),
          child: Text('Nenhum reservatório cadastrado para esta empresa.'),
        ),
      );
    }

    final total = reservoirs.length;
    final attention = reservoirs.where((r) => r.status != 'Limpa').length;
    final clean = total - attention;
    final cs = Theme.of(context).colorScheme;

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 720;
        final mapHeight = compact ? 390.0 : 470.0;

        return ListView(
          physics: _mapInteracting
              ? const NeverScrollableScrollPhysics()
              : const AlwaysScrollableScrollPhysics(),
          padding: EdgeInsets.fromLTRB(
            compact ? 14 : 20,
            16,
            compact ? 14 : 20,
            28,
          ),
          children: [
            // Cabeçalho da página
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: 44,
                  height: 44,
                  decoration: BoxDecoration(
                    color: cs.primaryContainer,
                    borderRadius: BorderRadius.circular(14),
                  ),
                  child: Icon(Icons.map_rounded, color: cs.primary),
                ),
                const SizedBox(width: 12),
                const Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Mapa',
                        style: TextStyle(
                          fontSize: 28,
                          height: 1.05,
                          fontWeight: FontWeight.w800,
                          letterSpacing: -.4,
                        ),
                      ),
                      SizedBox(height: 5),
                      Text(
                        'Localize e acompanhe os reservatórios monitorados.',
                        style: TextStyle(color: Colors.grey, fontSize: 13),
                      ),
                    ],
                  ),
                ),
                IconButton(
                  tooltip: 'Visualizar todos os reservatórios',
                  onPressed: () => setState(() => selected = null),
                  icon: const Icon(Icons.public_rounded),
                ),
              ],
            ),
            const SizedBox(height: 16),

            // Resumo rápido
            Row(
              children: [
                Expanded(
                  child: _MapSummaryCard(
                    icon: Icons.water_drop_rounded,
                    value: '$total',
                    label: 'Monitoradas',
                    color: cs.primary,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: _MapSummaryCard(
                    icon: Icons.check_circle_outline_rounded,
                    value: '$clean',
                    label: 'Em condição normal',
                    color: Colors.green.shade700,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: _MapSummaryCard(
                    icon: Icons.warning_amber_rounded,
                    value: '$attention',
                    label: 'Atenção',
                    color: Colors.orange.shade700,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 18),

            // Seletor de reservatórios
            Row(
              children: [
                const Expanded(
                  child: Text(
                    'Reservatórios',
                    style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800),
                  ),
                ),
                if (selected != null)
                  TextButton(
                    onPressed: () => setState(() => selected = null),
                    child: const Text('Mostrar todos'),
                  ),
              ],
            ),
            const SizedBox(height: 8),
            SizedBox(
              height: 104,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                itemCount: reservoirs.length,
                separatorBuilder: (_, __) => const SizedBox(width: 10),
                itemBuilder: (_, index) {
                  final r = reservoirs[index];
                  final active = selected?.id == r.id;
                  final status = statusLabel(r.status);

                  return Material(
                    color: Colors.transparent,
                    child: InkWell(
                      borderRadius: BorderRadius.circular(18),
                      onTap: () => selectReservoir(r),
                      child: AnimatedContainer(
                        duration: const Duration(milliseconds: 180),
                        curve: Curves.easeOut,
                        width: compact ? 205 : 225,
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: active ? cs.primaryContainer : cs.surface,
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color: active ? cs.primary : cs.outlineVariant,
                            width: active ? 1.8 : 1,
                          ),
                          boxShadow: active
                              ? [
                                  BoxShadow(
                                    color: cs.primary.withOpacity(.12),
                                    blurRadius: 16,
                                    offset: const Offset(0, 5),
                                  ),
                                ]
                              : null,
                        ),
                        child: Row(
                          children: [
                            Container(
                              width: 44,
                              height: 44,
                              decoration: BoxDecoration(
                                color: active
                                    ? cs.primary
                                    : cs.surfaceContainerHighest,
                                borderRadius: BorderRadius.circular(14),
                              ),
                              child: Icon(
                                Icons.water_drop_rounded,
                                color: active ? cs.onPrimary : cs.primary,
                                size: 21,
                              ),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    r.name,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w800,
                                      fontSize: 13,
                                    ),
                                  ),
                                  const SizedBox(height: 3),
                                  Text(
                                    r.location,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      fontSize: 11,
                                      color: Colors.grey,
                                    ),
                                  ),
                                  const SizedBox(height: 6),
                                  Row(
                                    children: [
                                      Container(
                                        width: 7,
                                        height: 7,
                                        decoration: BoxDecoration(
                                          color: statusColor(r.status),
                                          shape: BoxShape.circle,
                                        ),
                                      ),
                                      const SizedBox(width: 5),
                                      Flexible(
                                        child: Text(
                                          status,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: TextStyle(
                                            fontSize: 10.5,
                                            fontWeight: FontWeight.w700,
                                            color: statusColor(r.status),
                                          ),
                                        ),
                                      ),
                                    ],
                                  ),
                                ],
                              ),
                            ),
                            Icon(
                              active
                                  ? Icons.radio_button_checked_rounded
                                  : Icons.chevron_right_rounded,
                              size: 18,
                              color: active ? cs.primary : cs.outline,
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 16),

            // Contexto do mapa
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
              decoration: BoxDecoration(
                color: cs.surfaceContainerHighest.withOpacity(.55),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(color: cs.outlineVariant),
              ),
              child: Row(
                children: [
                  Icon(Icons.my_location_rounded, size: 18, color: cs.primary),
                  const SizedBox(width: 9),
                  Expanded(
                    child: Text(
                      selected == null
                          ? 'Visualizando todos os reservatórios da empresa'
                          : 'Centralizado em ${selected!.name}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                  if (selected != null)
                    TextButton(
                      onPressed: () => selectReservoir(selected!),
                      style: TextButton.styleFrom(
                        minimumSize: const Size(0, 32),
                        padding: const EdgeInsets.symmetric(horizontal: 8),
                      ),
                      child: const Text('Centralizar'),
                    ),
                ],
              ),
            ),
            const SizedBox(height: 10),

            // Mapa principal
            Card(
              clipBehavior: Clip.antiAlias,
              margin: EdgeInsets.zero,
              elevation: 0,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(22),
                side: BorderSide(color: cs.outlineVariant),
              ),
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(15, 13, 10, 11),
                    child: Row(
                      children: [
                        Container(
                          width: 34,
                          height: 34,
                          decoration: BoxDecoration(
                            color: cs.primaryContainer,
                            borderRadius: BorderRadius.circular(11),
                          ),
                          child: Icon(Icons.explore_outlined, size: 19, color: cs.primary),
                        ),
                        const SizedBox(width: 10),
                        const Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Localização',
                                style: TextStyle(fontWeight: FontWeight.w800),
                              ),
                              SizedBox(height: 2),
                              Text(
                                'Toque em um marcador para selecionar a caixa.',
                                style: TextStyle(fontSize: 11, color: Colors.grey),
                              ),
                            ],
                          ),
                        ),
                        IconButton(
                          tooltip: 'Abrir mapa ampliado',
                          onPressed: () {
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder: (_) => Scaffold(
                                  appBar: AppBar(title: const Text('Mapa dos reservatórios')),
                                  body: OsmMapWidget(
                                    companies: [widget.company],
                                    focusedReservoir: selected,
                                    showCompanyFilters: false,
                                    showMapOverlay: false,
                                    recenterToken: _recenterToken,
                                    onReservoirTap: selectReservoirFromMap,
                                  ),
                                ),
                              ),
                            );
                          },
                          icon: const Icon(Icons.fullscreen_rounded),
                        ),
                      ],
                    ),
                  ),
                  Listener(
                    onPointerDown: (_) {
                      if (mounted) setState(() => _mapInteracting = true);
                    },
                    onPointerUp: (_) {
                      if (mounted) setState(() => _mapInteracting = false);
                    },
                    onPointerCancel: (_) {
                      if (mounted) setState(() => _mapInteracting = false);
                    },
                    child: SizedBox(
                      height: mapHeight,
                      child: OsmMapWidget(
                        key: ValueKey(selected?.id ?? 'all-map'),
                        companies: [widget.company],
                        focusedReservoir: selected,
                        showCompanyFilters: false,
                        showMapOverlay: false,
                        recenterToken: _recenterToken,
                        onReservoirTap: selectReservoirFromMap,
                      ),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(14, 10, 14, 13),
                    child: Wrap(
                      spacing: 14,
                      runSpacing: 6,
                      children: [
                        _MapLegendDot(
                          color: Colors.green.shade700,
                          label: 'Normal',
                        ),
                        _MapLegendDot(
                          color: Colors.orange.shade700,
                          label: 'Atenção',
                        ),
                        _MapLegendDot(
                          color: Colors.red.shade700,
                          label: 'Crítico',
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),

            // Informações do reservatório selecionado
            if (selected != null) ...[
              const SizedBox(height: 12),
              Container(
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: cs.surface,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: cs.outlineVariant),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 42,
                      height: 42,
                      decoration: BoxDecoration(
                        color: cs.primaryContainer,
                        borderRadius: BorderRadius.circular(13),
                      ),
                      child: Icon(Icons.water_drop_rounded, color: cs.primary),
                    ),
                    const SizedBox(width: 11),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            selected!.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontWeight: FontWeight.w800),
                          ),
                          const SizedBox(height: 3),
                          Text(
                            '${selected!.location} • ${selected!.liters} L',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontSize: 11, color: Colors.grey),
                          ),
                        ],
                      ),
                    ),
                    StatusBadge(status: selected!.status),
                  ],
                ),
              ),
            ],
          ],
        );
      },
