}

class _MapSummaryCard extends StatelessWidget {
  final IconData icon;
  final String value;
  final String label;
  final Color color;

  const _MapSummaryCard({
    required this.icon,
    required this.value,
    required this.label,
    required this.color,
  });

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 11),
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: cs.outlineVariant),
      ),
      child: Row(
        children: [
          Icon(icon, size: 20, color: color),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  value,
                  style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w800),
                ),
                Text(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 9.5, color: Colors.grey),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _MapLegendDot extends StatelessWidget {
  final Color color;
  final String label;

  const _MapLegendDot({required this.color, required this.label});

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: 8,
          height: 8,
          decoration: BoxDecoration(color: color, shape: BoxShape.circle),
        ),
        const SizedBox(width: 5),
        Text(label, style: const TextStyle(fontSize: 10.5, color: Colors.grey)),
      ],
    );
  }
}

// ============================================================
// ANÁLISES + LAUDOS DO CLIENTE
// ============================================================

class ClientAnalysesReportsPage extends StatefulWidget {
  final Company company;
  final Reservoir? initialReservoir;
  final String? initialPoint;
  final String? initialParameter;
  final int initialSection;

  const ClientAnalysesReportsPage({
    super.key,
    required this.company,
    this.initialReservoir,
    this.initialPoint,
    this.initialParameter,
    this.initialSection = 0,
  });

  @override
  State<ClientAnalysesReportsPage> createState() => _ClientAnalysesReportsPageState();
}

class _ClientAnalysesReportsPageState extends State<ClientAnalysesReportsPage> {
  Reservoir? reservoir;
  String point = 'Todos';
  String parameter = 'Todos';
  DateTime? selectedDate;
  DateTime? bottomStartDate;
  DateTime? bottomEndDate;
  bool showAllBottomConditions = true;
  int section = 0; // 0 = análises, 1 = condições de fundo, 2 = laudos
  final search = TextEditingController();

  @override
  void initState() {
    super.initState();
    if (widget.initialReservoir != null &&
        widget.company.reservoirs.any((r) => r.id == widget.initialReservoir!.id)) {
      reservoir = widget.company.reservoirs.firstWhere((r) => r.id == widget.initialReservoir!.id);
    } else if (widget.company.reservoirs.isNotEmpty) {
      reservoir = widget.company.reservoirs.first;
    }
    if (widget.initialPoint == 'Todos' ||
        widget.initialPoint == 'P1' ||
        widget.initialPoint == 'P2' ||
        widget.initialPoint == 'P3') {
      point = widget.initialPoint!;
    }
    if (widget.initialParameter == 'Todos' ||
        widget.initialParameter == 'pH' ||
        widget.initialParameter == 'Turbidez' ||
        widget.initialParameter == 'TDS') {
      parameter = widget.initialParameter!;
    }
    section = widget.initialSection;
  }

  @override
  void dispose() {
    search.dispose();
    super.dispose();
  }

  String date(DateTime d) => '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';

  List<HistoryRecord> getRecords(Reservoir r) {
    var records = [...r.history]..sort((a,b) => b.date.compareTo(a.date));
    if (point != 'Todos') records = records.where((x) => x.point == point).toList();
    if (selectedDate != null) {
      records = records.where((x) => x.date.year == selectedDate!.year && x.date.month == selectedDate!.month && x.date.day == selectedDate!.day).toList();
    }
    return records;
  }

  List<BottomConditionRecord> getBottomRecords(Reservoir r) {
    final records = [...r.bottomHistory]..sort((a, b) => b.date.compareTo(a.date));
    if (showAllBottomConditions) return records;

    return records.where((record) {
      final day = DateTime(record.date.year, record.date.month, record.date.day);
      final start = bottomStartDate == null
          ? null
          : DateTime(bottomStartDate!.year, bottomStartDate!.month, bottomStartDate!.day);
      final end = bottomEndDate == null
          ? null
          : DateTime(bottomEndDate!.year, bottomEndDate!.month, bottomEndDate!.day);
      if (start != null && day.isBefore(start)) return false;
      if (end != null && day.isAfter(end)) return false;
      return true;
    }).toList();
  }

  Future<void> chooseBottomStartDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: bottomStartDate ?? bottomEndDate ?? DateTime.now(),
      firstDate: DateTime(2025),
      lastDate: DateTime.now(),
      helpText: 'Data inicial',
      cancelText: 'Cancelar',
      confirmText: 'Aplicar',
    );
    if (d != null) {
      setState(() {
        showAllBottomConditions = false;
        bottomStartDate = d;
        if (bottomEndDate != null && bottomEndDate!.isBefore(d)) {
          bottomEndDate = d;
        }
      });
    }
  }

  Future<void> chooseBottomEndDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: bottomEndDate ?? bottomStartDate ?? DateTime.now(),
      firstDate: DateTime(2025),
      lastDate: DateTime.now(),
      helpText: 'Data final',
      cancelText: 'Cancelar',
      confirmText: 'Aplicar',
    );
    if (d != null) {
      setState(() {
        showAllBottomConditions = false;
        bottomEndDate = d;
        if (bottomStartDate != null && bottomStartDate!.isAfter(d)) {
          bottomStartDate = d;
        }
      });
    }
  }

  void clearBottomDateFilter() {
    setState(() {
      showAllBottomConditions = true;
      bottomStartDate = null;
      bottomEndDate = null;
    });
  }

  String valueFor(HistoryRecord h) {
    switch (parameter) {
      case 'pH': return h.ph.toStringAsFixed(2);
      case 'Turbidez': return '${h.turbidity.toStringAsFixed(2)} NTU';
      case 'TDS': return '${h.tds.toStringAsFixed(0)} ppm';
      default: return 'pH ${h.ph.toStringAsFixed(2)} • ${h.turbidity.toStringAsFixed(2)} NTU • ${h.tds.toStringAsFixed(0)} ppm';
    }
  }

  List<DateTime> recentDates(Reservoir r) {
    final map = <String, DateTime>{};
    for (final h in r.history) {
      final d = DateTime(h.date.year, h.date.month, h.date.day);
      map['${d.year}-${d.month}-${d.day}'] = d;
    }
    for (final x in r.deletedAnalyses) {
      final d = DateTime(x.date.year, x.date.month, x.date.day);
      map['${d.year}-${d.month}-${d.day}'] = d;
    }
    final list = map.values.toList()..sort((a,b)=>b.compareTo(a));
    return list.take(12).toList();
  }

  Future<void> chooseDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: selectedDate ?? DateTime.now(),
      firstDate: DateTime(2025),
      lastDate: DateTime.now(),
      helpText: 'Filtrar por data',
      cancelText: 'Cancelar',
      confirmText: 'Aplicar',
    );
    if (d != null) setState(() => selectedDate = d);
  }

  void openReport(DateTime? day, {bool print = false}) {
    final r = reservoir;
    if (r == null) return;

    // Quando o usuário veio de uma data específica, o laudo é FIXO naquele dia.
    // Não mostramos uma segunda tela para escolher outra data ou período.
    if (day != null) {
      final start = DateTime(day.year, day.month, day.day, 0, 0, 0);
      final end = DateTime(day.year, day.month, day.day, 23, 59, 59);
      Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => ReportPage(
            reservoir: r,
            start: start,
            end: end,
            autoPrint: print,
          ),
        ),
      );
      return;
    }

    // A opção "Gerar laudo" sem uma data específica continua permitindo
    // escolher um período manualmente.
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => ReportSelectionPage(reservoir: r),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final r = reservoir;
    if (r == null) return const Center(child: Text('Nenhum reservatório cadastrado.'));

    final records = getRecords(r);
    final dates = recentDates(r);
    final latest = records.isNotEmpty ? records.first : null;
    final query = search.text.trim().toLowerCase();
    final filteredDates = dates.where((d) => '${date(d)} ${r.name}'.toLowerCase().contains(query)).toList();

    // Esta página também é aberta diretamente pelo monitoramento.
    // Quando é empurrada pelo Navigator, ela pode não estar sob um Scaffold
    // da página anterior; ChoiceChip/InputChip precisam de um Material
    // ancestral para serem construídos corretamente.
    return Material(
      color: Theme.of(context).scaffoldBackgroundColor,
      child: ListView(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 28),
        children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Análises e laudos', style: TextStyle(fontSize: 30, fontWeight: FontWeight.w800)),
                  SizedBox(height: 4),
                  Text('Histórico das medições e relatórios gerados pelo sistema.', style: TextStyle(color: Colors.grey)),
                ],
              ),
            ),
            if (latest != null) StatusBadge(status: latest.status),
          ],
        ),
        const SizedBox(height: 16),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              children: [
                DropdownButtonFormField<Reservoir>(
                  initialValue: r,
                  decoration: const InputDecoration(
                    labelText: 'Reservatório',
                    prefixIcon: Icon(Icons.water_drop_outlined),
                    border: OutlineInputBorder(),
                  ),
                  items: widget.company.reservoirs.map((x) => DropdownMenuItem(value: x, child: Text(x.name))).toList(),
                  onChanged: (v) => setState(() => reservoir = v),
                ),
                const SizedBox(height: 12),
                SegmentedButton<int>(
                  segments: const [
                    ButtonSegment(value: 0, icon: Icon(Icons.analytics_outlined), label: Text('Análises')),
                    ButtonSegment(value: 1, icon: Icon(Icons.waves_outlined), label: Text('Condições de fundo')),
                    ButtonSegment(value: 2, icon: Icon(Icons.description_outlined), label: Text('Laudos')),
                  ],
                  selected: {section},
                  onSelectionChanged: (v) => setState(() => section = v.first),
                ),
              ],
            ),
          ),
        ),
        const SizedBox(height: 14),
        if (section == 0) ...[
          Row(
            children: [
              const Expanded(child: Text('Resultados', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800))),
