class ClientCompanyProfilePage extends StatefulWidget {
  final Company company;
  const ClientCompanyProfilePage({super.key, required this.company});

  @override
  State<ClientCompanyProfilePage> createState() => _ClientCompanyProfilePageState();
}

class _ClientCompanyProfilePageState extends State<ClientCompanyProfilePage> {
  late final TextEditingController name;
  late final TextEditingController phone;
  late final TextEditingController email;
  final collaborator = TextEditingController();

  @override
  void initState() {
    super.initState();
    name = TextEditingController(text: widget.company.clientName);
    phone = TextEditingController(text: widget.company.clientPhone);
    email = TextEditingController(text: widget.company.clientEmail);
  }

  @override
  void dispose() {
    name.dispose(); phone.dispose(); email.dispose(); collaborator.dispose();
    super.dispose();
  }

  void save() {
    widget.company.clientName = name.text.trim();
    widget.company.clientPhone = phone.text.trim();
    widget.company.clientEmail = email.text.trim();
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Suas informações foram atualizadas.')),
    );
    setState(() {});
  }

  void addCollaborator() {
    final value = collaborator.text.trim();
    if (value.isEmpty) return;
    setState(() {
      widget.company.clientCollaborators.add(value);
      collaborator.clear();
    });
  }

  void contactSupport() {
    final text = Uri.encodeComponent('Olá, preciso de suporte no AquaMonitor. Empresa: ${widget.company.name}');
    html.window.open('https://api.whatsapp.com/send?text=$text', '_blank');
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Minha empresa')),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Card(
            child: Padding(
              padding: const EdgeInsets.all(18),
              child: Row(children: [
                CompanyAvatar(company: widget.company, radius: 34),
                const SizedBox(width: 14),
                Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(widget.company.name, style: const TextStyle(fontSize: 21, fontWeight: FontWeight.bold)),
                  Text(widget.company.location),
                  Text('Plano ${widget.company.plan.label}', style: const TextStyle(fontWeight: FontWeight.w600)),
                ])),
              ]),
            ),
          ),
          const SizedBox(height: 12),
          Card(child: ListTile(
            leading: const Icon(Icons.workspace_premium_outlined),
            title: Text('Plano ${widget.company.plan.label}'),
            subtitle: const Text('Plano definido pela administração. Para alterar, solicite um upgrade.'),
            trailing: OutlinedButton(onPressed: () => showDialog(context: context, builder: (_) => AlertDialog(
              title: const Text('Upgrade de plano'),
              content: const Text('Sua solicitação de upgrade será encaminhada ao suporte AquaMonitor.'),
              actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Fechar')), FilledButton(onPressed: () { Navigator.pop(context); contactSupport(); }, child: const Text('Solicitar'))],
            )), child: const Text('Upgrade')),
          )),
          const SizedBox(height: 12),
          Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Minhas informações', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold)),
            const SizedBox(height: 12),
            const Text('Você pode editar somente as informações adicionadas por você. Dados cadastrais definidos pelo administrador permanecem protegidos.'),
            const SizedBox(height: 12),
            TextField(controller: name, decoration: const InputDecoration(labelText: 'Meu nome / responsável interno', border: OutlineInputBorder())),
            const SizedBox(height: 10),
            TextField(controller: phone, decoration: const InputDecoration(labelText: 'Meu telefone', border: OutlineInputBorder())),
            const SizedBox(height: 10),
            TextField(controller: email, decoration: const InputDecoration(labelText: 'Meu e-mail', border: OutlineInputBorder())),
            const SizedBox(height: 12),
            FilledButton.icon(onPressed: save, icon: const Icon(Icons.save_outlined), label: const Text('Salvar minhas informações')),
          ]))),
          const SizedBox(height: 12),
          Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Colaboradores da empresa', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold)),
            const SizedBox(height: 6),
            const Text('Adicione colaboradores que você deseja registrar na sua área.'),
            const SizedBox(height: 12),
            Row(children: [Expanded(child: TextField(controller: collaborator, decoration: const InputDecoration(labelText: 'Nome do colaborador', border: OutlineInputBorder()))), const SizedBox(width: 8), IconButton(onPressed: addCollaborator, tooltip: 'Adicionar', icon: const Icon(Icons.person_add_alt_1))]),
            ...widget.company.clientCollaborators.map((c) => ListTile(leading: const Icon(Icons.person_outline), title: Text(c))),
          ]))),
          const SizedBox(height: 12),
          FilledButton.icon(onPressed: contactSupport, icon: const Icon(Icons.support_agent), label: const Text('Falar com o suporte pelo WhatsApp')),
        ],
      ),
    );
  }
}

class ClientMonitorHome extends StatefulWidget {
  final Company company;
  final Reservoir? initialReservoir;
  final String? initialPoint;
  final String? initialParameter;
  final bool standalone;
  final void Function(Reservoir reservoir, String point, String parameter)? onOpenAnalysis;
  final void Function(Reservoir reservoir)? onOpenBottomConditions;
  const ClientMonitorHome({
    super.key,
    required this.company,
    this.initialReservoir,
    this.initialPoint,
    this.initialParameter,
    this.standalone = false,
    this.onOpenAnalysis,
    this.onOpenBottomConditions,
  });

  @override
  State<ClientMonitorHome> createState() => _ClientMonitorHomeState();
}


class _ClientMonitorHomeState extends State<ClientMonitorHome> {
  Reservoir? selected;
  String selectedPoint = 'P1';
  int? selectedParameter = 1;
  DateTimeRange? reportRange;
  bool singleDate = true;
  DateTime singleReportDate = DateTime.now();

  @override
  void initState() {
    super.initState();
    if (widget.initialReservoir != null &&
        widget.company.reservoirs.any((r) => r.id == widget.initialReservoir!.id)) {
      selected = widget.company.reservoirs.firstWhere((r) => r.id == widget.initialReservoir!.id);
    } else if (widget.company.reservoirs.isNotEmpty) {
      selected = widget.company.reservoirs.first;
    }
    if (widget.initialPoint == 'P1' || widget.initialPoint == 'P2' || widget.initialPoint == 'P3') {
      selectedPoint = widget.initialPoint!;
    }
    if (widget.initialParameter == 'pH') selectedParameter = 0;
    if (widget.initialParameter == 'Turbidez') selectedParameter = 1;
    if (widget.initialParameter == 'TDS') selectedParameter = 2;
  }

  @override
  void didUpdateWidget(covariant ClientMonitorHome oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.initialReservoir != null &&
        widget.initialReservoir!.id != oldWidget.initialReservoir?.id) {
      final match = widget.company.reservoirs.where((r) => r.id == widget.initialReservoir!.id);
      if (match.isNotEmpty) selected = match.first;
    }
    if (widget.initialPoint != null && widget.initialPoint != oldWidget.initialPoint) {
      if (widget.initialPoint == 'P1' || widget.initialPoint == 'P2' || widget.initialPoint == 'P3') {
        selectedPoint = widget.initialPoint!;
      }
    }
    if (widget.initialParameter != null && widget.initialParameter != oldWidget.initialParameter) {
      if (widget.initialParameter == 'pH') selectedParameter = 0;
      if (widget.initialParameter == 'Turbidez') selectedParameter = 1;
      if (widget.initialParameter == 'TDS') selectedParameter = 2;
    }
  }

  String formatDate(DateTime d) =>
      '${d.day.toString().padLeft(2, '0')}/'
      '${d.month.toString().padLeft(2, '0')}/${d.year}';

  Future<void> chooseSingleDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: singleReportDate,
      firstDate: DateTime(2025),
      lastDate: DateTime.now(),
      helpText: 'Escolha a data',
    );
    if (picked != null) {
      setState(() {
        singleReportDate = picked;
        singleDate = true;
      });
    }
  }

  Future<void> chooseRange() async {
    final now = DateTime.now();
    final result = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2025),
      lastDate: now,
      initialDateRange: reportRange ??
          DateTimeRange(
            start: now.subtract(const Duration(days: 7)),
            end: now,
          ),
      helpText: 'Escolha o período do laudo',
    );
    if (result != null) {
      setState(() {
        reportRange = result;
        singleDate = false;
      });
    }
  }

  void openReport({bool print = false}) {
    final r = selected;
    if (r == null) return;

    if (!singleDate && reportRange == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Escolha o período do laudo antes de continuar.'),
        ),
      );
      return;
    }

    final start = singleDate
        ? DateTime(singleReportDate.year, singleReportDate.month, singleReportDate.day)
        : reportRange!.start;
    final end = singleDate
        ? DateTime(
            singleReportDate.year,
            singleReportDate.month,
            singleReportDate.day,
            23,
            59,
            59,
          )
        : DateTime(
            reportRange!.end.year,
            reportRange!.end.month,
            reportRange!.end.day,
            23,
            59,
            59,
          );

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => ReportPage(
          reservoir: r,
          start: start,
          end: end,
          autoPrint: print,
        ),
      ),
    );
  }

  String _pointName(String point) {
    switch (point) {
      case 'P1':
        return 'Superior';
      case 'P2':
        return 'Central';
      default:
        return 'Inferior';
    }
  }

  void _openParameterAnalysis(String parameter) {
    final reservoir = selected ??
        (widget.company.reservoirs.isNotEmpty
            ? widget.company.reservoirs.first
            : null);
    if (reservoir == null) return;

    if (widget.onOpenAnalysis != null) {
      widget.onOpenAnalysis!(reservoir, selectedPoint, parameter);
      return;
    }

    // Mantém o comportamento de tela independente apenas quando
    // o monitoramento for usado fora da navegação principal.
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => ClientAnalysesReportsPage(
          company: widget.company,
          initialReservoir: reservoir,
          initialPoint: selectedPoint,
          initialParameter: parameter,
          initialSection: 0,
        ),
      ),
    );
  }

  void _refresh() {
    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Monitoramento atualizado.'),
        duration: Duration(milliseconds: 900),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final reservoirs = widget.company.reservoirs;

    if (reservoirs.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(30),
          child: Text('Nenhum reservatório cadastrado para monitoramento.'),
        ),
      );
    }

    final r = selected ?? reservoirs.first;
    final reading = r.readingFor(selectedPoint);
    final cs = Theme.of(context).colorScheme;
    HistoryRecord? record;
    for (final item in r.history) {
      if (item.status != 'Limpa') {
        if (record == null || item.date.isAfter(record.date)) {
          record = item;
        }
      }
    }

    final content = RefreshIndicator(
      onRefresh: () async => setState(() {}),
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(18, 18, 18, 30),
        children: [
          // Cabeçalho da área de monitoramento.
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Pontos de medição',
                      style: TextStyle(
                        fontSize: 30,
                        height: 1.05,
                        fontWeight: FontWeight.w800,
                        color: cs.onSurface,
                      ),
                    ),
                    const SizedBox(height: 5),
                    Text(
                      'P1 = superior  •  P2 = central  •  P3 = inferior',
                      style: TextStyle(
                        fontSize: 15,
                        color: cs.onSurfaceVariant,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 10),
              OutlinedButton.icon(
                onPressed: () => Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => const SettingsPage(),
                  ),
                ),
                icon: const Icon(Icons.settings_outlined, size: 20),
                label: const Text('Configurações'),
                style: OutlinedButton.styleFrom(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 16,
                    vertical: 13,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(17),
                  ),
                  side: BorderSide(
                    color: cs.outlineVariant,
                  ),
                ),
              ),
            ],
          ),

          const SizedBox(height: 18),

          // Seletor de P1/P2/P3 no estilo da referência.
          _MonitorPointSelector(
            selectedPoint: selectedPoint,
            onChanged: (point) => setState(() {
              selectedPoint = point;
            }),
          ),

          const SizedBox(height: 12),

          // Caixa monitorada.
          Card(
            color: cs.surface,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(24),
            ),
            child: Padding(
              padding: const EdgeInsets.fromLTRB(14, 10, 14, 8),
