                child: DropdownButton<Reservoir>(
                  value: r,
                  isExpanded: true,
                  borderRadius: BorderRadius.circular(18),
                  icon: const Icon(Icons.keyboard_arrow_down_rounded),
                  onChanged: (value) {
                    if (value == null) return;
                    setState(() {
                      selected = value;
                      selectedPoint = 'P1';
                    });
                  },
                  items: reservoirs
                      .map(
                        (item) => DropdownMenuItem<Reservoir>(
                          value: item,
                          child: Row(
                            children: [
                              Container(
                                width: 38,
                                height: 38,
                                decoration: BoxDecoration(
                                  color: cs.primaryContainer,
                                  shape: BoxShape.circle,
                                ),
                                child: Icon(
                                  Icons.water_drop_rounded,
                                  color: cs.primary,
                                  size: 20,
                                ),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment:
                                      CrossAxisAlignment.start,
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Text(
                                      item.name,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                    Text(
                                      item.location,
                                      overflow: TextOverflow.ellipsis,
                                      style: TextStyle(
                                        fontSize: 12,
