    if (!widget.standalone) return content;

    final theme = Theme.of(context);
    final isLight = theme.brightness == Brightness.light;
    return Scaffold(
      backgroundColor: isLight ? const Color(0xFFF7F9FC) : theme.scaffoldBackgroundColor,
