class _MiniWavePainter extends CustomPainter {
  final Color color;

  const _MiniWavePainter(this.color);

  @override
  void paint(Canvas canvas, Size size) {
    if (size.width <= 2 || size.height <= 2) return;

    final path = Path();
    path.moveTo(0, size.height * .62);

    for (var i = 0; i <= 24; i++) {
      final x = size.width * i / 24;
      final y = size.height * .54 +
          math.sin(i * .65) * size.height * .18 +
          math.sin(i * .28) * size.height * .08;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }

    canvas.drawPath(
      path,
      Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.5
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );
  }

  @override
  bool shouldRepaint(covariant _MiniWavePainter oldDelegate) =>
      oldDelegate.color != color;
}


