class ReservoirDetailPage extends StatefulWidget {
  final Reservoir reservoir;

  const ReservoirDetailPage({super.key, required this.reservoir});

  @override
  State<ReservoirDetailPage> createState() => _ReservoirDetailPageState();
}

class _ReservoirDetailPageState extends State<ReservoirDetailPage> {
  int tab = 0;
  DateTimeRange? range;

  Future<void> pickRange() async {
    final now = DateTime.now();
    final result = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2025),
      lastDate: now.add(const Duration(days: 365)),
      initialDateRange: range ??
          DateTimeRange(
            start: now.subtract(const Duration(days: 7)),
            end: now,
          ),
    );
    if (result != null) setState(() => range = result);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(widget.reservoir.name)),
      body: Column(
