          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.all(10),
            child: Row(
              children: [
                DetailTab(
                  label: 'Monitor',
                  icon: Icons.monitor_heart_outlined,
                  selected: tab == 0,
                  onTap: () => setState(() => tab = 0),
