class MonitorPage extends StatefulWidget {
  final Reservoir reservoir;
  final void Function(Reservoir reservoir)? onOpenBottomConditions;
  const MonitorPage({super.key, required this.reservoir, this.onOpenBottomConditions});

  @override
  State<MonitorPage> createState() => _MonitorPageState();
}

class _MonitorPageState extends State<MonitorPage> {
  String point = 'P2';
  int parameter = 1;
  bool testing = false;

  PointReading get reading => widget.reservoir.readingFor(point);

  Future<void> refresh() async {
    setState(() => testing = true);
    await Future.delayed(const Duration(milliseconds: 700));
    if (!mounted) return;
    setState(() {
      testing = false;
      widget.reservoir.lastUpdate = DateTime.now();
    });
  }

  @override
  Widget build(BuildContext context) {
    final r = widget.reservoir;

    return LayoutBuilder(builder: (context, constraints) {
      final wide = constraints.maxWidth >= 900;
      final visual = Card(
        clipBehavior: Clip.antiAlias,
        child: Padding(
          padding: const EdgeInsets.all(14),
          child: Tank3D(
            reservoir: r,
            point: point,
            activeParameter: parameter,
            showValues: false,
          ),
        ),
      );

      final pointPanel = Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const Text('Pontos de coleta', style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          Row(
            children: ['P1', 'P2', 'P3'].map((p) {
              final selected = point == p;
              final pr = r.readingFor(p);
              return Expanded(
                child: Padding(
                  padding: const EdgeInsets.only(right: 7),
                  child: InkWell(
                    borderRadius: BorderRadius.circular(12),
                    onTap: () => setState(() => point = p),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 12),
                      decoration: BoxDecoration(
                        color: selected ? Theme.of(context).colorScheme.primaryContainer : Theme.of(context).colorScheme.surfaceContainerHighest,
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: selected ? Theme.of(context).colorScheme.primary : Colors.transparent, width: 1.5),
                      ),
                      child: Column(
                        children: [
                          Text(p, style: TextStyle(fontWeight: FontWeight.bold, color: selected ? Theme.of(context).colorScheme.primary : null)),
                          const SizedBox(height: 3),
                          Text(r.history.isEmpty ? 'Aguardando dados' : '${pr.turbidity.toStringAsFixed(2)} NTU', style: const TextStyle(fontSize: 11)),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            }).toList(),
          ),
          const SizedBox(height: 10),
          Builder(builder: (context) {
            final bottomRecords = [...r.bottomHistory]..sort((a, b) => b.date.compareTo(a.date));
            final bottom = bottomRecords.isNotEmpty ? bottomRecords.first : null;
            return InkWell(
              borderRadius: BorderRadius.circular(14),
              onTap: bottom == null ? null : () => widget.onOpenBottomConditions?.call(r),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: Theme.of(context).colorScheme.surfaceContainerHighest,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 42, height: 42,
                      decoration: BoxDecoration(
                        color: Theme.of(context).colorScheme.primaryContainer,
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: Icon(Icons.waves_rounded, color: Theme.of(context).colorScheme.primary),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text('Condições de fundo', style: TextStyle(fontWeight: FontWeight.w800)),
                          const SizedBox(height: 3),
                          Text('Após movimentação da bomba', style: TextStyle(fontSize: 12, color: Theme.of(context).colorScheme.onSurfaceVariant)),
                          const SizedBox(height: 7),
                          if (bottom == null)
                            const Text('Aguardando análise', style: TextStyle(fontSize: 12, color: Colors.grey))
                          else
                            Builder(builder: (context) {
                              final before = bottomBeforeReading(r, bottom);
                              return Row(
                                children: [
                                  Expanded(child: _MiniBottomPhase(title: 'Antes', ph: before.ph, turbidity: before.turbidity, tds: before.tds)),
                                  const SizedBox(width: 8),
                                  Expanded(child: _MiniBottomPhase(title: 'Depois', ph: bottom.ph, turbidity: bottom.turbidity, tds: bottom.tds)),
                                ],
                              );
                            }),
                        ],
                      ),
                    ),
                    if (bottom != null) const Icon(Icons.chevron_right_rounded),
                  ],
                ),
              ),
            );
          }),
          const SizedBox(height: 16),
          Card(
            color: Theme.of(context).colorScheme.surfaceContainerLowest,
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    CircleAvatar(radius: 16, child: Text(point)),
                    const SizedBox(width: 10),
                    const Expanded(child: Text('Leitura selecionada', style: TextStyle(fontWeight: FontWeight.bold))),
                    StatusBadge(status: r.history.isEmpty ? r.status : statusForTurbidity(reading.turbidity)),
                  ]),
                  const SizedBox(height: 14),
                  if (r.history.isEmpty)
                    const Text('Aguardando análise do equipamento. Os parâmetros aparecerão somente após a medição e o envio dos dados.', style: TextStyle(color: Colors.grey))
                  else ...[
                    _ReadingRow(label: 'pH', value: reading.ph.toStringAsFixed(2), selected: parameter == 0, onTap: () => setState(() => parameter = 0)),
                    _ReadingRow(label: 'Turbidez', value: '${reading.turbidity.toStringAsFixed(2)} NTU', selected: parameter == 1, onTap: () => setState(() => parameter = 1)),
                    _ReadingRow(label: 'TDS', value: '${reading.tds.toStringAsFixed(0)} ppm', selected: parameter == 2, onTap: () => setState(() => parameter = 2)),
                  ],
                ],
              ),
            ),
          ),
          const SizedBox(height: 10),
          Text('P1 superior • P2 central • P3 inferior', style: Theme.of(context).textTheme.bodySmall?.copyWith(color: Colors.grey)),
        ],
      );

      final header = Row(
        children: [
          const Expanded(child: Text('Monitoramento em tempo real', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold))),
          IconButton(tooltip: 'Atualizar leitura', onPressed: testing ? null : refresh, icon: testing ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.refresh)),
        ],
      );

      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          header,
          const SizedBox(height: 4),
          Text('Última leitura: ${r.lastUpdate.day.toString().padLeft(2, '0')}/${r.lastUpdate.month.toString().padLeft(2, '0')} às ${r.lastUpdate.hour.toString().padLeft(2, '0')}:${r.lastUpdate.minute.toString().padLeft(2, '0')}', style: const TextStyle(color: Colors.grey)),
          const SizedBox(height: 12),
          if (wide)
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(flex: 6, child: SizedBox(height: 430, child: visual)),
              const SizedBox(width: 14),
              Expanded(flex: 5, child: pointPanel),
            ])
          else ...[
            SizedBox(height: 340, child: visual),
            const SizedBox(height: 14),
            pointPanel,
          ],
        ],
      );
    });
  }
}

