class HistoryPage extends StatelessWidget {
  final Reservoir reservoir;
  final DateTimeRange? range;
  final VoidCallback onSelectRange;

  const HistoryPage({
    super.key,
    required this.reservoir,
    required this.range,
    required this.onSelectRange,
  });

  String date(DateTime d) =>
      '${d.day.toString().padLeft(2, '0')}/'
      '${d.month.toString().padLeft(2, '0')}';

  @override
  Widget build(BuildContext context) {
    final records = reservoir.history;
    return ListView(
      padding: const EdgeInsets.all(18),
      children: [
        Row(
          children: [
            const Expanded(
              child: Text(
                'Histórico',
                style: TextStyle(fontSize: 27, fontWeight: FontWeight.bold),
              ),
            ),
            FilledButton.tonalIcon(
              onPressed: onSelectRange,
              icon: const Icon(Icons.date_range),
              label: const Text('Período'),
            ),
          ],
        ),
        const SizedBox(height: 8),
        Text(
          range == null
              ? 'Últimos registros'
              : '${date(range!.start)} até ${date(range!.end)}',
          style: const TextStyle(color: Colors.grey),
        ),
        const SizedBox(height: 14),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: SizedBox(
              height: 320,
              child: DetailedHistoryChart(records: records),
            ),
          ),
        ),
        const SizedBox(height: 14),
        const Text(
          'Registros detalhados',
          style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 8),
        ...records.reversed.map(
          (x) => Card(
            child: ListTile(
              leading: CircleAvatar(child: Text(x.point)),
              title: Text(
                '${date(x.date)} • ${statusLabel(x.status)}',
              ),
              subtitle: Text(
                'pH ${x.ph.toStringAsFixed(2)} • '
                'Turbidez ${x.turbidity.toStringAsFixed(2)} NTU • '
                'TDS ${x.tds.toStringAsFixed(0)} ppm',
              ),
              trailing: StatusBadge(status: x.status),
            ),
          ),
        ),
        const SizedBox(height: 12),
        FilledButton.icon(
          onPressed: () {
            final end = DateTime.now();
            final start =
                range?.start ?? end.subtract(const Duration(days: 7));
            Navigator.push(
              context,
              MaterialPageRoute(
                builder: (_) => ReportPage(
                  reservoir: reservoir,
                  start: start,
                  end: range?.end ?? end,
                ),
              ),
            );
          },
          icon: const Icon(Icons.description_outlined),
          label: const Text('Emitir laudo deste período'),
        ),
      ],
    );
  }
}

String statusLabel(String s) {
  if (s == 'Limpa' || s == 'Normal') return 'Caixa limpa';
  if (s == 'Atenção') return 'Atenção';
  if (s == 'Aguardando análise') return 'Aguardando análise';
  return 'Caixa suja';
}

Color statusColor(String status) {
  switch (status) {
    case 'Limpa':
    case 'Normal':
      return const Color(0xFF2E7D32);
    case 'Atenção':
      return const Color(0xFFF9A825);
    case 'Suja':
      return const Color(0xFFC62828);
    default:
      return const Color(0xFF607D8B);
  }
}

class DetailedHistoryChart extends StatelessWidget {
  final List<HistoryRecord> records;
  final DateTime? start;
  final DateTime? end;
  final String parameter;

  const DetailedHistoryChart({
    super.key,
    required this.records,
    this.start,
    this.end,
    this.parameter = 'Turbidez',
  });

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      painter: DetailedHistoryPainter(
        records,
        start: start,
        end: end,
        parameter: parameter,
      ),
      child: const SizedBox.expand(),
    );
  }
}

class DetailedHistoryPainter extends CustomPainter {
  final List<HistoryRecord> records;
  final DateTime? start;
  final DateTime? end;
  final String parameter;

  DetailedHistoryPainter(
    this.records, {
    this.start,
    this.end,
    this.parameter = 'Turbidez',
  });

  String _two(int n) => n.toString().padLeft(2, '0');
  String _dateLabel(DateTime d) => '${_two(d.day)}/${_two(d.month)}';
  String _timeLabel(DateTime d) => '${_two(d.hour)}:${_two(d.minute)}';

  double _value(HistoryRecord r) {
    switch (parameter) {
      case 'pH':
        return r.ph;
      case 'TDS':
        return r.tds;
      case 'Turbidez':
      default:
        return r.turbidity;
    }
  }

  String _unit() {
    switch (parameter) {
      case 'pH': return '';
      case 'TDS': return 'ppm';
      case 'Turbidez': return 'NTU';
      default: return '';
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (records.isEmpty) return;

    final sorted = [...records]..sort((a, b) => a.date.compareTo(b.date));
    final first = start ?? sorted.first.date;
    final last = end ?? sorted.last.date;
    final graphStart = DateTime(first.year, first.month, first.day, first.hour, first.minute, first.second);
    final graphEnd = DateTime(last.year, last.month, last.day, last.hour, last.minute, last.second);
    final totalMs = math.max(1, graphEnd.difference(graphStart).inMilliseconds);
    final singleDay = graphStart.year == graphEnd.year && graphStart.month == graphEnd.month && graphStart.day == graphEnd.day;

    final grid = Paint()..color = Colors.grey.withValues(alpha: .18)..strokeWidth = 1;
    final line = Paint()..color = const Color(0xFF087E8B)..strokeWidth = 2.8..style = PaintingStyle.stroke;
    final dot = Paint()..style = PaintingStyle.fill;
    final left = 54.0;
    final right = size.width - 14;
    final top = 38.0;
    final bottom = size.height - 58;

    final values = sorted.map(_value).toList();
    double minValue;
    double maxValue;
    if (parameter == 'pH') {
      minValue = math.min(0, values.reduce(math.min));
      maxValue = math.max(14, values.reduce(math.max));
    } else {
      minValue = math.min(0, values.reduce(math.min));
      final spread = values.reduce(math.max) - values.reduce(math.min);
      maxValue = math.max(values.reduce(math.max) + math.max(.1, spread * .12), 1);
    }
    if ((maxValue - minValue).abs() < .0001) maxValue = minValue + 1;

    for (int i = 0; i < 5; i++) {
      final y = top + (bottom - top) * i / 4;
      canvas.drawLine(Offset(left, y), Offset(right, y), grid);
    }

    double xFor(DateTime d) {
      final elapsed = d.difference(graphStart).inMilliseconds;
      final fraction = (elapsed / totalMs).clamp(0.0, 1.0);
      return left + (right - left) * fraction;
    }

    if (singleDay) {
      const totalSeconds = 23 * 3600 + 59 * 60 + 59;
      double xHour(int hour) => left + (right - left) * ((hour * 3600) / totalSeconds);
      const hours = [0, 6, 12, 18, 23];
      for (final hour in hours) {
        final x = xHour(hour);
        canvas.drawLine(Offset(x, top), Offset(x, bottom), grid);
        final tp = TextPainter(
          text: TextSpan(text: '${_two(hour)}:00', style: const TextStyle(fontSize: 9, color: Colors.grey, fontWeight: FontWeight.w600)),
          textDirection: TextDirection.ltr,
        )..layout();
        tp.paint(canvas, Offset(x - tp.width / 2, bottom + 8));
      }
    } else {
      final dayCount = DateTime(graphEnd.year, graphEnd.month, graphEnd.day)
              .difference(DateTime(graphStart.year, graphStart.month, graphStart.day)).inDays + 1;
      final step = math.max(1, (dayCount / 6).ceil());
      int dayIndex = 0;
      DateTime cursor = DateTime(graphStart.year, graphStart.month, graphStart.day);
      while (!cursor.isAfter(DateTime(graphEnd.year, graphEnd.month, graphEnd.day))) {
        if (dayIndex % step == 0 || (cursor.day == graphEnd.day && cursor.month == graphEnd.month && cursor.year == graphEnd.year)) {
          final x = xFor(cursor);
          canvas.drawLine(Offset(x, top), Offset(x, bottom), grid);
          final tp = TextPainter(
            text: TextSpan(text: _dateLabel(cursor), style: const TextStyle(fontSize: 9, color: Colors.grey, fontWeight: FontWeight.w600)),
            textDirection: TextDirection.ltr,
          )..layout();
          tp.paint(canvas, Offset(x - tp.width / 2, bottom + 8));
        }
        cursor = cursor.add(const Duration(days: 1));
        dayIndex++;
      }
    }

    double yFor(double value) => bottom - ((value - minValue) / (maxValue - minValue)) * (bottom - top);
    final path = Path();
    for (int i = 0; i < sorted.length; i++) {
      final record = sorted[i];
      final x = xFor(record.date);
      final y = yFor(_value(record));
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }

      dot.color = record.status == 'Suja' ? Colors.red : record.status == 'Atenção' ? Colors.orange : Colors.green;
      canvas.drawCircle(Offset(x, y), 5, dot);

      final showLabel = singleDay || sorted.length <= 10;
      if (showLabel) {
        final valueText = _value(record).toStringAsFixed(parameter == 'TDS' ? 0 : 2);
        final label = TextPainter(
          text: TextSpan(
            text: singleDay
                ? '${_timeLabel(record.date)}\n$valueText'
                : '${_dateLabel(record.date)} ${_timeLabel(record.date)}\n$valueText',
            style: TextStyle(fontSize: 8.5, color: dot.color, fontWeight: FontWeight.bold),
          ),
          textDirection: TextDirection.ltr,
          textAlign: TextAlign.center,
        )..layout(maxWidth: 82);
        final labelX = (x - label.width / 2).clamp(left, right - label.width);
        final labelY = math.max(top, y - label.height - 7);
        label.paint(canvas, Offset(labelX, labelY));
      }
    }
    canvas.drawPath(path, line);

    final title = TextPainter(
      text: TextSpan(
        text: parameter == 'pH'
            ? (singleDay ? 'pH • evolução ao longo do dia' : 'pH • evolução no período selecionado')
            : parameter == 'TDS'
                ? (singleDay ? 'TDS (ppm) • evolução ao longo do dia' : 'TDS (ppm) • evolução no período selecionado')
                : (singleDay ? 'Turbidez (NTU) • evolução ao longo do dia' : 'Turbidez (NTU) • evolução no período selecionado'),
        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    title.paint(canvas, Offset(left, 8));

    if (parameter == 'Turbidez') {
      final y2 = yFor(2.0);
      final threshold = Paint()..color = Colors.orange..strokeWidth = 1.5;
      canvas.drawLine(Offset(left, y2), Offset(right, y2), threshold);
    }

    final unit = _unit();
    final maxLabel = TextPainter(
      text: TextSpan(text: '${maxValue.toStringAsFixed(parameter == 'TDS' ? 0 : 1)}$unit', style: const TextStyle(fontSize: 9, color: Colors.grey)),
      textDirection: TextDirection.ltr,
    )..layout();
    maxLabel.paint(canvas, Offset(2, top - 4));
  }

  @override
  bool shouldRepaint(covariant DetailedHistoryPainter oldDelegate) =>
      oldDelegate.records != records || oldDelegate.start != start || oldDelegate.end != end || oldDelegate.parameter != parameter;
}

