// LAUDO
// ============================================================

class ReportPage extends StatelessWidget {
  final Reservoir reservoir;
  final DateTime start;
  final DateTime end;
  final bool autoPrint;
  final List<String> parameters;

  const ReportPage({
    super.key,
    required this.reservoir,
    required this.start,
    required this.end,
    this.autoPrint = false,
    this.parameters = const ['Turbidez', 'pH', 'TDS'],
  });

  String date(DateTime d) =>
      '${d.day.toString().padLeft(2, '0')}/'
      '${d.month.toString().padLeft(2, '0')}/${d.year}';

  void printReport() {
    // Abre uma página HTML temporária diretamente pelo clique do usuário.
    // Isso evita acessar WindowBase.document, que não existe na API dart:html.
    final records = reservoir.history.where((r) =>
        !r.date.isBefore(start) && !r.date.isAfter(end)).toList()
      ..sort((a, b) => a.date.compareTo(b.date));
    final bottomRecords = [...reservoir.bottomHistory]
      ..removeWhere((r) => r.date.isBefore(start) || r.date.isAfter(end))
      ..sort((a, b) => a.date.compareTo(b.date));

    String esc(String value) => value
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;');

    String d(DateTime x) =>
        '${x.day.toString().padLeft(2, '0')}/${x.month.toString().padLeft(2, '0')}/${x.year}';
    String t(DateTime x) =>
        '${x.hour.toString().padLeft(2, '0')}:${x.minute.toString().padLeft(2, '0')}';

    final headers = <String>['Data/hora', 'Ponto'];
    if (parameters.contains('Turbidez')) headers.add('Turbidez');
    if (parameters.contains('pH')) headers.add('pH');
    if (parameters.contains('TDS')) headers.add('TDS');
    headers.add('Status');

    final headHtml = headers.map((h) => '<th>$h</th>').join();
    final rowsHtml = records.map((r) {
      final cells = <String>['${d(r.date)} ${t(r.date)}', esc(r.point)];
      if (parameters.contains('Turbidez')) cells.add('${r.turbidity.toStringAsFixed(2)} NTU');
      if (parameters.contains('pH')) cells.add(r.ph.toStringAsFixed(2));
      if (parameters.contains('TDS')) cells.add('${r.tds.toStringAsFixed(0)} ppm');
      cells.add(esc(r.status));
      return '<tr>${cells.map((c) => '<td>$c</td>').join()}</tr>';
    }).join();

    final bottomRowsHtml = bottomRecords.map((b) {
      final before = bottomBeforeReading(reservoir, b);
      return '<tr><td>${d(b.date)} ${t(b.date)}</td><td>Antes: ${before.ph.toStringAsFixed(2)}<br>Depois: ${b.ph.toStringAsFixed(2)}</td><td>Antes: ${before.turbidity.toStringAsFixed(2)} NTU<br>Depois: ${b.turbidity.toStringAsFixed(2)} NTU</td><td>Antes: ${before.tds.toStringAsFixed(0)} ppm<br>Depois: ${b.tds.toStringAsFixed(0)} ppm</td><td>${esc(b.status)}</td></tr>';
    }).join();

    final parameterLabel = parameters.map((p) =>
        esc(p == 'TDS' ? 'TDS • sólidos dissolvidos' : p)).join(', ');

    // Gera gráficos SVG independentes para a versão impressa do laudo.
    // O SVG é incorporado diretamente no HTML, portanto não depende de
    // Canvas, Flutter ou recursos externos e aparece também no PDF/impresso.
    String printChart(String parameter) {
      if (records.isEmpty) return '';
      double valueOf(HistoryRecord r) {
        if (parameter == 'pH') return r.ph;
        if (parameter == 'TDS') return r.tds.toDouble();
        return r.turbidity;
      }
      String unit = parameter == 'pH' ? '' : parameter == 'TDS' ? ' ppm' : ' NTU';
      final values = records.map(valueOf).toList();
      var minV = values.reduce((a, b) => a < b ? a : b);
      var maxV = values.reduce((a, b) => a > b ? a : b);
      if ((maxV - minV).abs() < 0.000001) {
        minV -= 1;
        maxV += 1;
      } else {
        final pad = (maxV - minV) * 0.12;
        minV -= pad;
        maxV += pad;
      }
      final startMs = start.millisecondsSinceEpoch.toDouble();
      final endMs = end.millisecondsSinceEpoch.toDouble();
      final span = (endMs - startMs).abs() < 1 ? 1.0 : endMs - startMs;
      const left = 58.0, top = 28.0, width = 650.0, height = 230.0;
      final points = <String>[];
      for (final r in records) {
        final x = left + ((r.date.millisecondsSinceEpoch - startMs) / span) * width;
        final y = top + height - ((valueOf(r) - minV) / (maxV - minV)) * height;
        points.add('${x.toStringAsFixed(1)},${y.toStringAsFixed(1)}');
      }
      final dots = <String>[];
      for (var i = 0; i < records.length; i++) {
        final r = records[i];
        final x = left + ((r.date.millisecondsSinceEpoch - startMs) / span) * width;
        final y = top + height - ((valueOf(r) - minV) / (maxV - minV)) * height;
        final label = '${d(r.date)} ${t(r.date)} • ${valueOf(r).toStringAsFixed(parameter == 'TDS' ? 0 : 2)}$unit';
        dots.add('<circle cx="${x.toStringAsFixed(1)}" cy="${y.toStringAsFixed(1)}" r="4" fill="#087E8B"><title>${esc(label)}</title></circle>');
      }
      String xLabel(DateTime dt) => '${dt.day.toString().padLeft(2,'0')}/${dt.month.toString().padLeft(2,'0')}';
      final ticks = <String>[];
      for (var i = 0; i < 5; i++) {
        final ratio = i / 4;
        final x = left + width * ratio;
        final ms = startMs + span * ratio;
        final dt = DateTime.fromMillisecondsSinceEpoch(ms.round());
        ticks.add('<line x1="${x.toStringAsFixed(1)}" y1="$top" x2="${x.toStringAsFixed(1)}" y2="${(top+height).toStringAsFixed(1)}" stroke="#e2e8f0"/><text x="${x.toStringAsFixed(1)}" y="285" text-anchor="middle" font-size="10" fill="#64748b">${xLabel(dt)}</text>');
      }
      final yTicks = <String>[];
      for (var i = 0; i < 5; i++) {
        final ratio = i / 4;
        final y = top + height - height * ratio;
        final v = minV + (maxV - minV) * ratio;
        yTicks.add('<line x1="$left" y1="${y.toStringAsFixed(1)}" x2="${(left+width).toStringAsFixed(1)}" y2="${y.toStringAsFixed(1)}" stroke="#e2e8f0"/><text x="50" y="${(y+4).toStringAsFixed(1)}" text-anchor="end" font-size="10" fill="#64748b">${v.toStringAsFixed(parameter == 'TDS' ? 0 : 2)}</text>');
      }
      final poly = points.join(' ');
      final safeTitle = esc(parameter == 'TDS' ? 'TDS • sólidos dissolvidos (ppm)' : '$parameter${unit.isEmpty ? '' : ' ($unit)'}');
      return '''<div class="chartBlock">
<h3>$safeTitle</h3>
<svg viewBox="0 0 750 315" role="img" aria-label="$safeTitle - evolução no período">
${ticks.join()}
${yTicks.join()}
<polyline points="$poly" fill="none" stroke="#087E8B" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>
${dots.join()}
</svg>
</div>''';
    }

    final printCharts = parameters.map(printChart).join('');

    final content = '''
<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<title>AquaMonitor - Laudo - ${esc(reservoir.name)}</title>
<style>
@page { size:A4; margin:15mm; }
body{font-family:Arial,Helvetica,sans-serif;color:#172033;margin:0;background:#fff}
h1{font-size:24px;margin:0 0 6px}h2{font-size:17px;margin:22px 0 9px}
.brand{font-size:12px;letter-spacing:2px;font-weight:700;color:#087E8B}
.header{border-bottom:3px solid #087E8B;padding-bottom:14px;margin-bottom:18px}
.meta{line-height:1.7;color:#475569}.badge{margin-top:10px;padding:8px 10px;background:#eef8f6;border-radius:8px}
table{width:100%;border-collapse:collapse;font-size:10.5px}th,td{border:1px solid #d9e1e8;padding:7px;text-align:left}th{background:#f1f5f9}
.cards{display:flex;gap:8px;flex-wrap:wrap}.card{border:1px solid #d9e1e8;border-radius:9px;padding:9px 12px;min-width:105px}
.note{background:#eef8f6;border-left:4px solid #087E8B;padding:11px;line-height:1.5}
.chartBlock{margin:14px 0 20px;page-break-inside:avoid}.chartBlock h3{font-size:13px;margin:0 0 5px}.chartBlock svg{display:block;width:100%;height:auto;border:1px solid #e2e8f0;border-radius:8px;background:#fff}
.footer{margin-top:25px;padding-top:9px;border-top:1px solid #d9e1e8;font-size:9px;color:#64748b}
</style>
</head>
<body>
<div class="header">
<div class="brand">AQUAMONITOR</div>
<h1>Laudo de monitoramento do reservatório</h1>
<div class="meta"><strong>Reservatório:</strong> ${esc(reservoir.name)}<br>
<strong>Local:</strong> ${esc(reservoir.location)}<br>
<strong>Capacidade:</strong> ${reservoir.liters} L<br>
<strong>Período:</strong> ${d(start)} a ${d(end)}<br>
<strong>Parâmetros:</strong> $parameterLabel</div>
<div class="badge">${records.length} registro(s) encontrado(s) no período selecionado.</div>
</div>
<h2>Resumo do monitoramento</h2>
<div class="cards">
<div class="card"><b>Registros</b><br>${records.length}</div>
<div class="card"><b>Limpa</b><br>${records.where((r) => r.status == 'Limpa').length}</div>
<div class="card"><b>Atenção</b><br>${records.where((r) => r.status == 'Atenção').length}</div>
<div class="card"><b>Suja</b><br>${records.where((r) => r.status == 'Suja').length}</div>
</div>
<h2>Registros do período</h2>
${records.isEmpty ? '<div class="note">Nenhum registro foi encontrado no período selecionado.</div>' : '<table><thead><tr>$headHtml</tr></thead><tbody>$rowsHtml</tbody></table>'}
${records.isEmpty ? '' : '<h2>Gráficos de evolução</h2>$printCharts'}
<h2>Condições de fundo</h2>
<div class="note">Análises realizadas após a movimentação controlada da bomba.</div>
${bottomRecords.isEmpty ? '<div class="note">Nenhuma condição de fundo registrada no período selecionado.</div>' : '<table><thead><tr><th>Data/hora</th><th>pH</th><th>Turbidez</th><th>TDS</th><th>Status</th></tr></thead><tbody>$bottomRowsHtml</tbody></table>'}
<h2>Interpretação do monitoramento</h2>
<div class="note">O presente documento apresenta os registros obtidos pelo sistema de monitoramento no período selecionado. A interpretação deve considerar os critérios experimentais definidos no projeto e não substitui análises laboratoriais ou inspeções sanitárias.</div>
<div class="footer">AquaMonitor • Documento gerado a partir dos registros do período selecionado.</div>
<script>window.onload=function(){setTimeout(function(){window.print();},300);};</script>
</body></html>''';

    final blob = html.Blob(
      [content],
      'text/html;charset=utf-8',
    );
    final printUrl = html.Url.createObjectUrlFromBlob(blob);

    // A nova aba é aberta no próprio gesto do usuário. O HTML contém
    // window.onload -> window.print(), disparando o diálogo nativo após o
    // documento terminar de carregar.
    html.window.open(printUrl, '_blank');

    // Libera o objeto depois que a nova aba já teve tempo de carregá-lo.
    Future<void>.delayed(const Duration(seconds: 10), () {
      html.Url.revokeObjectUrl(printUrl);
    });
  }

  @override
  Widget build(BuildContext context) {
    // Não disparar window.print() automaticamente após a navegação.
    // O navegador pode bloquear esse tipo de impressão porque o gesto do
    // usuário já terminou. O botão de impressão desta tela chama printReport()
    // diretamente.
    if (autoPrint) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (context.mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Laudo pronto. Toque no ícone de impressão para imprimir.')),
          );
        }
      });
    }
    final records = reservoir.history.where((r) =>
        !r.date.isBefore(start) && !r.date.isAfter(end)).toList();
    final bottomRecords = [...reservoir.bottomHistory]
      ..removeWhere((r) => r.date.isBefore(start) || r.date.isAfter(end))
      ..sort((a, b) => a.date.compareTo(b.date));
    final deleted = reservoir.deletedAnalyses.where((d) =>
        !d.date.isBefore(DateTime(start.year, start.month, start.day)) &&
        !d.date.isAfter(DateTime(end.year, end.month, end.day))).toList();
    final hasExactRecord = records.isNotEmpty;
    final clean = records.where((r) => r.status == 'Limpa').length;
    final attention = records.where((r) => r.status == 'Atenção').length;
    final dirty = records.where((r) => r.status == 'Suja').length;

    return Theme(
      data: ThemeData(
        useMaterial3: true,
        brightness: Brightness.light,
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFF087E8B),
        ),
        scaffoldBackgroundColor: Colors.white,
        cardColor: Colors.white,
      ),
      child: Scaffold(
        backgroundColor: Colors.white,
        appBar: AppBar(
          backgroundColor: Colors.white,
          foregroundColor: Colors.black87,
          surfaceTintColor: Colors.white,
          title: const Text('Laudo de monitoramento'),
          actions: [
            IconButton(
              tooltip: 'Imprimir laudo',
              onPressed: printReport,
              icon: const Icon(Icons.print_outlined),
            ),
          ],
        ),
        body: ListView(
          padding: const EdgeInsets.all(20),
          children: [
            Card(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    'AQUAMONITOR',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      letterSpacing: 2,
                    ),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'LAUDO DE MONITORAMENTO DE RESERVATÓRIO',
                    style: TextStyle(
                      fontSize: 25,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const Divider(height: 30),
                  Text('Reservatório: ${reservoir.name}'),
                  Text('Local: ${reservoir.location}'),
                  Text('Capacidade: ${reservoir.liters} L'),
                  Text('Tipo: ${reservoir.type}'),
                  Text(start.year == end.year && start.month == end.month && start.day == end.day
                      ? 'Data: ${date(start)} • 00:00–23:59'
                      : 'Período: ${date(start)} a ${date(end)}'),
                  const SizedBox(height: 10),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
                    decoration: BoxDecoration(
                      color: hasExactRecord
                          ? Colors.green.withValues(alpha: .10)
                          : Colors.orange.withValues(alpha: .12),
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Row(
                      children: [
                        Icon(
                          hasExactRecord ? Icons.check_circle_outline : Icons.info_outline,
                          size: 18,
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            hasExactRecord
                                ? 'Registros encontrados ao longo do dia selecionado (00:00–23:59).'
                                : deleted.isNotEmpty
                                    ? 'A análise da data selecionada foi excluída e não é apresentada no gráfico.'
                                    : 'Não há registros para o dia selecionado. O gráfico não apresenta dados de outros dias.',
                            style: const TextStyle(fontSize: 12),
                          ),
                        ),
                      ],
                    ),
                  ),
                  if (deleted.isNotEmpty) ...[
                    const SizedBox(height: 16),
                    Container(
                      padding: const EdgeInsets.all(16),
                      decoration: BoxDecoration(
                        border: Border.all(color: Colors.deepOrange.shade300),
                        borderRadius: BorderRadius.circular(12),
                        color: Colors.orange.withValues(alpha: .08),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Row(
                            children: [
                              Icon(Icons.verified_outlined, color: Colors.deepOrange),
                              SizedBox(width: 8),
                              Expanded(child: Text('CERTIFICADO DE ALTERAÇÃO — VERIFICAÇÃO DIGITAL', style: TextStyle(fontWeight: FontWeight.bold))),
                            ],
                          ),
                          const SizedBox(height: 10),
                          ...deleted.map((d) => Padding(
                            padding: const EdgeInsets.only(bottom: 10),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Data da análise: ${date(d.date)}', style: const TextStyle(fontWeight: FontWeight.bold)),
                                Text('Motivo informado pelo administrador: ${d.reason}'),
                                Text('Excluída por: ${d.deletedBy}'),
                                Text('Registro efetuado em: ${date(d.deletedAt)}'),
                                SelectableText('Código de verificação: ${d.verificationCode}', style: const TextStyle(fontFamily: 'monospace', fontWeight: FontWeight.bold)),
                              ],
                            ),
                          )),
                          const Text('As medições dessa data foram removidas do histórico e não são apresentadas no gráfico. Este registro permanece para rastreabilidade da alteração.'),
                        ],
                      ),
                    ),
                  ],
                  const SizedBox(height: 22),
                  const Text(
                    'Resumo do monitoramento',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 10),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: [
                      if (parameters.contains('pH')) _ReportStat(title: 'pH', value: records.isEmpty ? '—' : records.first.ph.toStringAsFixed(2)),
                      if (parameters.contains('Turbidez')) _ReportStat(title: 'Turbidez', value: records.isEmpty ? '—' : '${records.first.turbidity.toStringAsFixed(2)} NTU'),
                      if (parameters.contains('TDS')) _ReportStat(title: 'TDS', value: records.isEmpty ? '—' : '${records.first.tds.toStringAsFixed(0)} ppm'),
                      _ReportStat(title: 'Limpa', value: '$clean registros'),
                      _ReportStat(title: 'Atenção', value: '$attention registros'),
                      _ReportStat(title: 'Suja', value: '$dirty registros'),
                    ],
                  ),
                  const SizedBox(height: 24),
                  const Text('Parâmetros selecionados', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 8),
                  Text(parameters.isEmpty ? 'Nenhum parâmetro selecionado.' : parameters.join(' • '), style: const TextStyle(color: Colors.grey)),
                  const SizedBox(height: 18),
                  const Text('Gráficos de evolução', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 8),
                  if (records.isEmpty)
                    const SizedBox(height: 180, child: Center(child: Text('Sem dados registrados para a data/período selecionado.', textAlign: TextAlign.center, style: TextStyle(color: Colors.grey))))
                  else if (parameters.isEmpty)
                    const SizedBox(height: 120, child: Center(child: Text('Selecione pelo menos um parâmetro para visualizar o laudo.')))
                  else
                    ...parameters.map((parameter) => Padding(
                      padding: const EdgeInsets.only(bottom: 18),
                      child: SizedBox(
                        height: 300,
                        child: DetailedHistoryChart(records: records, start: start, end: end, parameter: parameter),
                      ),
                    )),
                  const SizedBox(height: 20),
                  const Text(
                    'Condições de fundo',
                    style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold),
                  ),
                  const SizedBox(height: 6),
                  const Text(
                    'Análises realizadas após a movimentação controlada da bomba.',
                    style: TextStyle(color: Colors.grey),
                  ),
                  const SizedBox(height: 10),
                  if (bottomRecords.isEmpty)
                    const Text('Nenhuma condição de fundo registrada no período selecionado.', style: TextStyle(color: Colors.grey))
                  else
                    ...bottomRecords.map((b) => Card(
                      child: Padding(
                        padding: const EdgeInsets.all(14),
                        child: Row(
                          children: [
                            Expanded(child: Text('${date(b.date)} • ${b.date.hour.toString().padLeft(2,'0')}:${b.date.minute.toString().padLeft(2,'0')}\nAntes e depois da movimentação da bomba', style: const TextStyle(fontWeight: FontWeight.w600))),
                            Builder(builder: (context) {
                              final before = bottomBeforeReading(reservoir, b);
                              return Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                                Text('ANTES • pH ${before.ph.toStringAsFixed(2)}'),
                                Text('Turbidez ${before.turbidity.toStringAsFixed(2)} NTU'),
                                Text('TDS ${before.tds.toStringAsFixed(0)} ppm'),
                                const SizedBox(height: 5),
                                Text('DEPOIS • pH ${b.ph.toStringAsFixed(2)}'),
                                Text('Turbidez ${b.turbidity.toStringAsFixed(2)} NTU'),
                                Text('TDS ${b.tds.toStringAsFixed(0)} ppm'),
                              ]);
                            }),
                          ],
                        ),
                      ),
                    )),
                  const SizedBox(height: 20),
                  const Text(
                    'Interpretação do monitoramento',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    'O gráfico apresenta a evolução da turbidez por dia, '
                    'associando cada registro à situação identificada pelo '
                    'critério experimental do sistema: caixa limpa, atenção '
                    'ou caixa suja. As medições devem ser avaliadas em conjunto '
                    'com pH, TDS, ponto de coleta e histórico.',
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'Parâmetros monitorados',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    [
                      if (parameters.contains('pH')) 'pH: indicador do caráter ácido, neutro ou alcalino da água.',
                      if (parameters.contains('Turbidez')) 'Turbidez: indicador óptico associado à presença de partículas em suspensão.',
                      if (parameters.contains('TDS')) 'TDS: estimativa da concentração de sólidos dissolvidos por meio da resposta do sensor utilizado.',
                    ].join('\n'),
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'Pontos de coleta',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'P1 – região superior; P2 – região central; '
                    'P3 – região inferior. A inspeção de fundo pode utilizar '
                    'o P3 com procedimento controlado de agitação.',
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'Observação técnica',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'Este documento é um laudo relacionado ao monitoramento '
                    'realizado pelo sistema AquaMonitor. Ele não substitui '
                    'análises laboratoriais, inspeções sanitárias ou demais '
                    'procedimentos exigidos. A ausência de manutenção, limpeza '
                    'adequada, calibração dos sensores ou condições apropriadas '
                    'do reservatório pode influenciar as medições e, '
                    'consequentemente, a interpretação dos resultados.',
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'Conclusão',
                    style: TextStyle(
                      fontSize: 19,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    records.isEmpty
                        ? 'Não há leitura disponível para o período selecionado. Consulte a verificação digital acima quando houver exclusão registrada.'
                        : 'Situação da leitura registrada: ${statusLabel(records.last.status)}. Recomenda-se considerar a tendência histórica e os registros por ponto antes de tomar qualquer decisão de manutenção.',
                  ),
                ],
              ),
            ),
          ),
          ],
        ),
      ),
    );
  }
}

class _MiniBottomPhase extends StatelessWidget {
  final String title;
  final double ph;
  final double turbidity;
  final double tds;

  const _MiniBottomPhase({required this.title, required this.ph, required this.turbidity, required this.tds});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(9),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(10),
        color: Theme.of(context).colorScheme.surface,
        border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(title, style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800)),
        const SizedBox(height: 4),
        Text('pH ${ph.toStringAsFixed(2)}', style: const TextStyle(fontSize: 11)),
        Text('Turbidez ${turbidity.toStringAsFixed(2)} NTU', style: const TextStyle(fontSize: 11)),
        Text('TDS ${tds.toStringAsFixed(0)} ppm', style: const TextStyle(fontSize: 11)),
      ]),
    );
  }
}

class _BottomComparisonCard extends StatelessWidget {
  final String title;
  final String subtitle;
  final double ph;
  final double turbidity;
  final double tds;
  final IconData icon;

  const _BottomComparisonCard({required this.title, required this.subtitle, required this.ph, required this.turbidity, required this.tds, required this.icon});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surface,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(icon, size: 18, color: Theme.of(context).colorScheme.primary),
          const SizedBox(width: 6),
          Expanded(child: Text(title, style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w800))),
