class _InspectionPageState extends State<InspectionPage> {
  bool running = false;
  String result = 'Nenhum teste realizado.';

  Future<void> runInspection() async {
    setState(() {
      running = true;
      result = 'Comando de inspeção enviado ao controlador...';
    });

    await Future.delayed(const Duration(milliseconds: 900));

    setState(() {
      running = false;
      result =
          'Inspeção concluída no P3. Variação simulada de turbidez: '
          '0,82 NTU. Na versão integrada, a ESP32 enviará as leituras reais.';
    });
  }

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.all(18),
      children: [
        const Text(
          'Inspeção de fundo',
          style: TextStyle(fontSize: 27, fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 6),
        const Text(
          'Avaliação experimental da região inferior da caixa.',
          style: TextStyle(color: Colors.grey),
        ),
        const SizedBox(height: 18),
        Card(
          child: ListTile(
            leading: const CircleAvatar(child: Text('P3')),
            title: const Text('Ponto inferior'),
            subtitle: Text(
              'Turbidez atual: ${widget.reservoir.readingFor('P3').turbidity.toStringAsFixed(2)} NTU',
            ),
          ),
        ),
        const SizedBox(height: 14),
        FilledButton.icon(
          onPressed: running ? null : runInspection,
          icon: running
              ? const SizedBox(
                  width: 18,
                  height: 18,
                  child: CircularProgressIndicator(strokeWidth: 2),
                )
              : const Icon(Icons.play_arrow),
          label: Text(
            running
                ? 'Realizando inspeção...'
                : 'Realizar inspeção de fundo',
          ),
        ),
        const SizedBox(height: 14),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(18),
            child: Text(result),
          ),
        ),
      ],
    );
  }
}

