class ClientReports extends StatefulWidget {
  final Company company;
  const ClientReports({super.key, required this.company});
  @override State<ClientReports> createState()=>_ClientReportsState();
}

class _ClientReportsState extends State<ClientReports> {
  final search = TextEditingController();
  @override void dispose(){ search.dispose(); super.dispose(); }

  String f(DateTime d) => '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';

  List<DateTime> recentDates(Reservoir r) {
    final map = <String, DateTime>{};
    for (final h in r.history) {
      final d = DateTime(h.date.year, h.date.month, h.date.day);
      map['${d.year}-${d.month}-${d.day}'] = d;
    }
    for (final x in r.deletedAnalyses) {
      final d = DateTime(x.date.year, x.date.month, x.date.day);
      map['${d.year}-${d.month}-${d.day}'] = d;
    }
    final list = map.values.toList()..sort((a,b)=>b.compareTo(a));
    return list.take(8).toList();
  }

  @override
  Widget build(BuildContext context) {
    final list = widget.company.reservoirs.where((r) => r.name.toLowerCase().contains(search.text.toLowerCase())).toList();
    return ListView(
      padding: const EdgeInsets.fromLTRB(16,14,16,28),
      children: [
        const Text('Laudos', style: TextStyle(fontSize:30,fontWeight:FontWeight.w800)),
        const Text('Relatórios recentes e acesso ao histórico de cada reservatório.', style: TextStyle(color:Colors.grey)),
        const SizedBox(height:16),
        TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Pesquisar reservatório',border:OutlineInputBorder())),
        const SizedBox(height:14),
        ...list.map((r) {
          final dates = recentDates(r);
          return Card(
            child: ExpansionTile(
              leading: Container(width:46,height:46,decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(14)),child:Icon(Icons.description_outlined,color:Theme.of(context).colorScheme.primary)),
              title: Text(r.name,style:const TextStyle(fontWeight:FontWeight.w800)),
              subtitle: Text('${r.location} • ${dates.length} laudo(s) recente(s)'),
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16,0,16,14),
                  child: Column(
                    children: [
                      Align(alignment:Alignment.centerLeft,child:Text(dates.isEmpty?'Nenhum laudo disponível':'Laudos recentes',style:const TextStyle(fontWeight:FontWeight.w700))),
                      const SizedBox(height:8),
                      if (dates.isEmpty)
                        const ListTile(leading:Icon(Icons.hourglass_empty),title:Text('Aguardando análise'),subtitle:Text('O laudo aparecerá depois que o sistema registrar dados.'))
                      else
                        ...dates.map((d) {
                          final deleted = r.deletedAnalyses.any((x)=>x.date.year==d.year&&x.date.month==d.month&&x.date.day==d.day);
                          final count = r.history.where((h)=>h.date.year==d.year&&h.date.month==d.month&&h.date.day==d.day).length;
                          return Card(
                            color: Theme.of(context).colorScheme.surfaceContainerHighest,
                            child: ListTile(
                              leading: Icon(deleted?Icons.gpp_bad_outlined:Icons.description_outlined),
                              title: Text(f(d)),
                              subtitle: Text(deleted?'Análise removida • ver auditoria':'$count registro(s) de análise'),
                              trailing: const Icon(Icons.chevron_right_rounded),
                              onTap: ()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ReportSelectionPage(reservoir:r,initialDay:d))),
                            ),
                          );
                        }),
                    ],
                  ),
                ),
              ],
            ),
          );
        }).toList(),
        if(list.isEmpty) const Padding(padding:EdgeInsets.all(24),child:Text('Nenhum reservatório encontrado.')),
      ],
    );
  }
}

class ReportSelectionPage extends StatefulWidget {
  final Reservoir reservoir;
  final DateTime? initialDay;
  const ReportSelectionPage({super.key, required this.reservoir, this.initialDay});
  @override State<ReportSelectionPage> createState() => _ReportSelectionPageState();
}

class _ReportSelectionPageState extends State<ReportSelectionPage> {
  bool single = true;
  DateTime day = DateTime.now();
  DateTimeRange? range;
  final Set<String> selectedParameters = {'Turbidez', 'pH', 'TDS'};

  @override
  void initState() {
    super.initState();
    if (widget.initialDay != null) day = widget.initialDay!;
  }

  String f(DateTime d) => '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';

  void open({bool print = false}) {
    if (selectedParameters.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Selecione pelo menos um parâmetro.')));
      return;
    }
    if (!single && range == null) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Escolha o período do laudo antes de continuar.')));
      return;
    }
    final start = single ? DateTime(day.year, day.month, day.day) : range!.start;
    final end = single ? DateTime(day.year, day.month, day.day, 23, 59, 59) : DateTime(range!.end.year, range!.end.month, range!.end.day, 23, 59, 59);
    Navigator.push(context, MaterialPageRoute(builder: (_) => ReportPage(
      reservoir: widget.reservoir,
      start: start,
      end: end,
      autoPrint: print,
      parameters: selectedParameters.toList(),
    )));
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text('Laudo • ${widget.reservoir.name}')),
    body: ListView(
      padding: const EdgeInsets.all(20),
      children: [
        const Text('Período do laudo', style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold)),
        const SizedBox(height: 12),
        SegmentedButton<bool>(
          segments: const [ButtonSegment(value:true,label:Text('Data única')),ButtonSegment(value:false,label:Text('Período'))],
          selected: {single},
          onSelectionChanged: (v) => setState(() => single = v.first),
        ),
        const SizedBox(height: 12),
        if (single)
          OutlinedButton.icon(
            onPressed: () async {
              final x = await showDatePicker(context:context, initialDate:day, firstDate:DateTime(2025), lastDate:DateTime.now());
              if (x != null) setState(() => day=x);
            },
            icon: const Icon(Icons.event),
            label: Text(f(day)),
          )
        else
          OutlinedButton.icon(
            onPressed: () async {
              final now = DateTime.now();
              final x = await showDateRangePicker(context:context, firstDate:DateTime(2025), lastDate:now, initialDateRange:range ?? DateTimeRange(start:now.subtract(const Duration(days:7)), end:now));
              if (x != null) setState(() => range=x);
            },
            icon: const Icon(Icons.date_range),
            label: Text(range==null ? 'Escolher período' : '${f(range!.start)} até ${f(range!.end)}'),
          ),
        const SizedBox(height: 22),
        const Text('Parâmetros do laudo', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800)),
        const SizedBox(height: 6),
        const Text('Escolha quais parâmetros serão apresentados no resumo e nos gráficos deste laudo.', style: TextStyle(color: Colors.grey)),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: ['Turbidez', 'pH', 'TDS'].map((p) => FilterChip(
            label: Text(p == 'TDS' ? 'TDS • sólidos dissolvidos' : p),
            selected: selectedParameters.contains(p),
            onSelected: (value) => setState(() {
              if (value) { selectedParameters.add(p); } else { selectedParameters.remove(p); }
            }),
          )).toList(),
        ),
        const SizedBox(height: 20),
        Row(
          children: [
            Expanded(child: FilledButton.icon(onPressed:()=>open(),icon:const Icon(Icons.visibility),label:const Text('Visualizar'))),
            const SizedBox(width:8),
            Expanded(child: OutlinedButton.icon(onPressed:()=>open(print:true),icon:const Icon(Icons.print),label:const Text('Imprimir'))),
          ],
        ),
      ],
    ),
  );
}

