HistoryRecord? _latestInconformity(Reservoir reservoir) {
  final candidates = reservoir.history
      .where((h) => h.status != 'Limpa')
      .toList()
    ..sort((a, b) => b.date.compareTo(a.date));
  return candidates.isEmpty ? null : candidates.first;
}

