class _ClientMessagesState extends State<ClientMessages> {
  AppNotification? _highlightedNotification;
  final Map<AppNotification, GlobalKey> _messageKeys = {};

  @override
  void initState() {
    super.initState();
    _highlightedNotification = widget.initialNotification;
    if (_highlightedNotification != null) {
      _highlightedNotification!.read = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        // O posicionamento é feito uma única vez e sem animação contínua.
        // Isso evita o ciclo de atualização do ponteiro do Flutter Web (mouse_tracker).
        Future.delayed(const Duration(milliseconds: 80), () {
          if (!mounted) return;
          final key = _messageKeys[_highlightedNotification];
          final target = key?.currentContext;
          if (target != null) {
            Scrollable.ensureVisible(
              target,
              duration: Duration.zero,
              alignment: .35,
            );
          }
          Future.delayed(const Duration(milliseconds: 1200), () {
            if (mounted) setState(() => _highlightedNotification = null);
          });
        });
      });
    }
  }

  String _date(DateTime d) =>
      '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';

  String _time(DateTime d) =>
      '${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';

  List<AppNotification> get _messages => demoNotifications
      .where((n) => n.companyId == widget.company.id && !n.dismissedByClient)
      .toList()
    ..sort((a, b) => a.date.compareTo(b.date));

  String _parameterForNotification(AppNotification n, HistoryRecord? record) {
    if (n.parameter != null && n.parameter!.trim().isNotEmpty) return n.parameter!;
    final text = '${n.title} ${n.message}'.toLowerCase();
    if (text.contains('turbidez')) return 'Turbidez';
    if (text.contains('ph')) return 'pH';
    if (text.contains('tds') || text.contains('sólidos dissolvidos') || text.contains('solidos dissolvidos')) return 'TDS';
    return 'Turbidez';
  }

  void _openMessage(AppNotification n) {
    // A mensagem do cliente é somente uma conversa de transmissão.
    // Nunca navegamos diretamente para ReportPage/ReservoirDetailPage ao tocar no balão,
    // evitando que uma tela externa provoque overflow no DartPad.
    setState(() => n.read = true);
    final r = reservoirById(n.companyId, n.reservoirId);
    final cs = Theme.of(context).colorScheme;

    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      backgroundColor: Theme.of(context).scaffoldBackgroundColor,
      builder: (sheetContext) {
        return DraggableScrollableSheet(
          expand: false,
          initialChildSize: .58,
          minChildSize: .35,
          maxChildSize: .88,
          builder: (_, controller) {
            return Material(
              color: Theme.of(context).scaffoldBackgroundColor,
              child: ListView(
                controller: controller,
                padding: const EdgeInsets.fromLTRB(20, 4, 20, 28),
                children: [
                  Row(
                    children: [
                      Container(
                        width: 44,
                        height: 44,
                        decoration: BoxDecoration(
                          color: cs.primaryContainer,
                          shape: BoxShape.circle,
                        ),
                        child: Icon(Icons.support_agent_rounded, color: cs.primary),
                      ),
                      const SizedBox(width: 12),
                      const Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('Administração', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800)),
                            Text('Mensagem recebida', style: TextStyle(fontSize: 12, color: Colors.grey)),
                          ],
                        ),
                      ),
                      IconButton(
                        tooltip: 'Fechar',
                        onPressed: () => Navigator.pop(sheetContext),
                        icon: const Icon(Icons.close_rounded),
                      ),
                    ],
                  ),
                  const SizedBox(height: 18),
                  Text(
                    n.title,
                    style: const TextStyle(fontSize: 21, fontWeight: FontWeight.w800),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    n.message,
                    style: const TextStyle(fontSize: 15, height: 1.5),
                  ),
                  const SizedBox(height: 18),
                  Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: cs.surface,
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(color: cs.outlineVariant.withValues(alpha: .55)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('Detalhes da mensagem', style: TextStyle(fontWeight: FontWeight.w800)),
                        const SizedBox(height: 12),
                        if (r != null) ...[
                          _MessageDetailRow(icon: Icons.water_drop_outlined, label: 'Reservatório', value: r.name),
                          const SizedBox(height: 9),
                        ],
                        _MessageDetailRow(icon: Icons.schedule_rounded, label: 'Enviada em', value: '${_date(n.date)} às ${_time(n.date)}'),
                        if (n.analysisDate != null) ...[
                          const SizedBox(height: 9),
                          _MessageDetailRow(icon: Icons.description_outlined, label: 'Análise relacionada', value: _date(n.analysisDate!)),
                        ],
                      ],
                    ),
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton.icon(
                      onPressed: () {
                        Navigator.pop(sheetContext);
                        if (r == null) {
                          Navigator.push(
                            context,
                            MaterialPageRoute(builder: (_) => ClientGeneralMessagePage(notification: n)),
                          );
                          return;
                        }
                        HistoryRecord? related;
                        if (n.analysisDate == null) {
                          related = _latestInconformity(r);
                        } else {
                          final d = n.analysisDate!;
                          final sameDay = r.history.where((h) =>
                            h.date.year == d.year && h.date.month == d.month && h.date.day == d.day,
                          ).toList()..sort((a, b) => b.date.compareTo(a.date));
                          related = sameDay.isEmpty ? _latestInconformity(r) : sameDay.first;
                        }
                        final parameter = _parameterForNotification(n, related);
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => ClientInconformityPage(
                              reservoir: r,
                              record: related,
                              parameter: parameter,
                              onVerify: widget.onVerify == null
                                  ? null
                                  : () => widget.onVerify!(r, related?.point ?? 'P2', parameter),
                            ),
                          ),
                        );
                      },
                      icon: const Icon(Icons.description_outlined),
                      label: const Text('Expandir'),
                      style: OutlinedButton.styleFrom(
                        padding: const EdgeInsets.symmetric(vertical: 13),
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      ),
                    ),
                  ),
                  const SizedBox(height: 18),
                  Container(
                    padding: const EdgeInsets.all(13),
                    decoration: BoxDecoration(
                      color: cs.primaryContainer.withValues(alpha: .45),
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(Icons.lock_outline_rounded, size: 18, color: cs.primary),
                        const SizedBox(width: 9),
                        Expanded(
                          child: Text(
                            'Este canal é somente para visualização. As mensagens são enviadas pela administração e permanecem no histórico da empresa.',
                            style: TextStyle(fontSize: 12, height: 1.4, color: cs.onSurfaceVariant),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final messages = _messages;
    final unread = messages.where((n) => !n.read).length;

    return Scaffold(
