class NotificationBell extends StatefulWidget {
  final String? companyId;
  final VoidCallback? onOpenMessages;
  final ValueChanged<AppNotification>? onOpenNotification;
  const NotificationBell({super.key, this.companyId, this.onOpenMessages, this.onOpenNotification});

  @override
  State<NotificationBell> createState() => _NotificationBellState();
}

class _NotificationBellState extends State<NotificationBell> {
  List<AppNotification> get _visible => demoNotifications.where((n) {
    if (n.dismissedFromBell) return false;
    if (widget.companyId != null && n.companyId != widget.companyId) return false;
    return true;
  }).toList()..sort((a, b) => b.date.compareTo(a.date));

  void open(AppNotification n) {
    setState(() => n.read = true);
    if (widget.onOpenNotification != null) {
      widget.onOpenNotification!(n);
      return;
    }
    if (widget.onOpenMessages != null) {
      widget.onOpenMessages!();
      return;
    }
    final r = reservoirById(n.companyId, n.reservoirId);
    if (r == null) return;
    if (n.analysisDate != null) {
      final d = n.analysisDate!;
      Navigator.push(context, MaterialPageRoute(builder: (_) => ReportPage(
        reservoir: r,
        start: DateTime(d.year, d.month, d.day),
        end: DateTime(d.year, d.month, d.day, 23, 59, 59),
      )));
    } else {
      Navigator.push(context, MaterialPageRoute(builder: (_) => ReservoirDetailPage(reservoir: r)));
    }
  }

  String _time(DateTime d) => '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')} • ${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';

  @override
  Widget build(BuildContext context) {
    final visible = _visible;
    final unread = visible.where((n) => !n.read).length;
    return IconButton(
      tooltip: 'Notificações',
      onPressed: () => showModalBottomSheet(
        context: context,
        isScrollControlled: true,
        showDragHandle: true,
        backgroundColor: Theme.of(context).scaffoldBackgroundColor,
        builder: (_) => StatefulBuilder(builder: (context, modalSetState) {
          final list = _visible;
          return SafeArea(
            child: SizedBox(
              height: MediaQuery.sizeOf(context).height * .72,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(18, 4, 18, 18),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    Container(width: 42, height: 42, decoration: BoxDecoration(color: Theme.of(context).colorScheme.primaryContainer, borderRadius: BorderRadius.circular(14)), child: Icon(Icons.notifications_rounded, color: Theme.of(context).colorScheme.primary)),
                    const SizedBox(width: 10),
                    const Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Notificações', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w800)), SizedBox(height: 2), Text('Acesso rápido às novidades')])) ,
                    if (list.isNotEmpty)
                      TextButton(
                        onPressed: () {
                          for (final n in list) {
                            n.read = true;
                          }
                          modalSetState(() {});
                          setState(() {});
                        },
                        child: const Text('Ler todas'),
                      ),
                  ]),
                  const SizedBox(height: 4),
                  Text(unread == 0 ? 'Tudo em dia' : '$unread ${unread == 1 ? 'nova' : 'novas'}', style: TextStyle(color: Theme.of(context).colorScheme.onSurfaceVariant)),
                  const SizedBox(height: 14),
                  Expanded(child: list.isEmpty
                    ? _SoftEmptyState(icon: Icons.notifications_none_rounded, title: 'Nenhuma notificação', message: 'Quando uma nova mensagem chegar, ela aparecerá aqui.')
                    : ListView.separated(
                        itemCount: list.length,
                        separatorBuilder: (_, __) => const SizedBox(height: 8),
                        itemBuilder: (_, i) {
                          final n = list[i];
                          final r = reservoirById(n.companyId, n.reservoirId);
                          return _BellNotificationTile(
                            notification: n,
                            reservoirName: r?.name,
                            timeLabel: _time(n.date),
                            onTap: () { Navigator.pop(context); open(n); },
                            onDelete: () {
                              // Excluir aqui apenas limpa o sininho.
                              // A conversa permanece intacta na tela de mensagens.
                              n.dismissedFromBell = true;
                              modalSetState(() {});
                              setState(() {});
                            },
                          );
                        },
                      )),
                ]),
              ),
            ),
          );
        }),
      ),
      icon: Badge(isLabelVisible: unread > 0, label: Text('$unread'), child: const Icon(Icons.notifications_none_rounded)),
    );
  }
}

class _SoftEmptyState extends StatelessWidget {
  final IconData icon; final String title; final String message;
  const _SoftEmptyState({required this.icon, required this.title, required this.message});
  @override
  Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [
    Container(width: 68, height: 68, decoration: BoxDecoration(color: Theme.of(context).colorScheme.primaryContainer, shape: BoxShape.circle), child: Icon(icon, size: 32, color: Theme.of(context).colorScheme.primary)),
    const SizedBox(height: 14), Text(title, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w800)), const SizedBox(height: 6), Text(message, textAlign: TextAlign.center, style: TextStyle(color: Theme.of(context).colorScheme.onSurfaceVariant)),
  ])));
}

class _BellNotificationTile extends StatelessWidget {
  final AppNotification notification;
  final String? reservoirName;
  final String timeLabel;
  final VoidCallback onTap;
  final VoidCallback onDelete;
  const _BellNotificationTile({required this.notification, required this.reservoirName, required this.timeLabel, required this.onTap, required this.onDelete});

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Material(
      color: cs.surfaceContainerHighest,
      borderRadius: BorderRadius.circular(20),
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: onTap,
        child: Padding(
          padding: const EdgeInsets.all(13),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Container(width: 42, height: 42, decoration: BoxDecoration(color: notification.read ? cs.surface : cs.primaryContainer, shape: BoxShape.circle), child: Icon(notification.read ? Icons.notifications_none_rounded : Icons.notifications_active_rounded, color: notification.read ? cs.onSurfaceVariant : cs.primary)),
            const SizedBox(width: 11),
            Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [Expanded(child: Text(notification.title, style: TextStyle(fontWeight: notification.read ? FontWeight.w600 : FontWeight.w800))), if (!notification.read) Container(width: 8, height: 8, decoration: BoxDecoration(color: cs.primary, shape: BoxShape.circle))]),
              const SizedBox(height: 4),
              Text(notification.message, maxLines: 2, overflow: TextOverflow.ellipsis, style: TextStyle(color: cs.onSurfaceVariant, height: 1.3)),
              const SizedBox(height: 7),
              Text('${reservoirName ?? 'Reservatório'} • $timeLabel', style: TextStyle(fontSize: 11, color: cs.onSurfaceVariant)),
            ])),
            const SizedBox(width: 4),
            IconButton(tooltip: 'Apagar do sininho', onPressed: onDelete, icon: Icon(Icons.delete_outline_rounded, color: cs.onSurfaceVariant)),
          ]),
        ),
      ),
    );
  }
}

