        if(showCompanies) ...companies.map((c)=>ExpansionTile(leading:CompanyAvatar(company:c,radius:20),title:Text(c.name,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${c.reservoirs.length} caixa(s) • ${c.plan.label}'),children:c.reservoirs.map((r)=>ListTile(title:Text(r.name),subtitle:Text(r.location),trailing:StatusBadge(status:r.status),onTap:()=>_openMap(context,r))).toList())),
