class CompanyAvatar extends StatelessWidget {
  final Company company;
  final double radius;

  const CompanyAvatar({
    super.key,
    required this.company,
    this.radius = 26,
  });

  @override
  Widget build(BuildContext context) {
    final logo = company.logoUrl.trim();
    if (logo.isNotEmpty) {
      if (logo.startsWith('data:image/')) {
        try {
          final comma = logo.indexOf(',');
          final bytes = base64Decode(
            comma >= 0 ? logo.substring(comma + 1) : logo,
          );
          return CircleAvatar(
            radius: radius,
            backgroundImage: MemoryImage(bytes),
          );
        } catch (_) {
          // Se a imagem enviada estiver inválida, usa o avatar padrão.
        }
      } else {
        return CircleAvatar(
          radius: radius,
          backgroundImage: NetworkImage(logo),
        );
      }
    }

    return CircleAvatar(
      radius: radius,
      backgroundColor: company.color,
      child: Text(
        company.name.isEmpty ? '?' : company.name[0].toUpperCase(),
        style: TextStyle(
          color: Theme.of(context).colorScheme.onPrimary,
          fontWeight: FontWeight.bold,
          fontSize: radius * .7,
        ),
      ),
    );
  }
}

