class AdminCompanyDetail extends StatefulWidget {
  final Company company;

  const AdminCompanyDetail({super.key, required this.company});

  @override
  State<AdminCompanyDetail> createState() => _AdminCompanyDetailState();
}

class _AdminCompanyDetailState extends State<AdminCompanyDetail> {
  Future<void> addReservoir() async {
    final r = await showDialog<Reservoir>(
      context: context,
      builder: (_) => ReservoirEditorDialog(
        company: widget.company,
      ),
    );
    if (r != null) setState(() => widget.company.reservoirs.add(r));
  }

  Future<void> editReservoir(Reservoir r) async {
    final updated = await showDialog<Reservoir>(
      context: context,
      builder: (_) => ReservoirEditorDialog(
        company: widget.company,
        reservoir: r,
      ),
    );
    if (updated != null) {
      final i = widget.company.reservoirs.indexOf(r);
      setState(() => widget.company.reservoirs[i] = updated);
    }
  }

  void addContact() {
    final c = TextEditingController();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Adicionar responsável'),
        content: TextField(
          controller: c,
          decoration: const InputDecoration(labelText: 'Nome'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancelar'),
          ),
          FilledButton(
            onPressed: () {
              if (c.text.trim().isNotEmpty) {
                setState(() => widget.company.contacts.add(c.text.trim()));
              }
              Navigator.pop(context);
            },
            child: const Text('Adicionar'),
          ),
        ],
      ),
    );
  }

  Future<void> manageAnalyses(Reservoir reservoir) async {
    await showDialog<void>(
      context: context,
      builder: (_) => _AnalysisManagementDialog(reservoir: reservoir),
    );
    if (mounted) setState(() {});
  }

  Future<void> confirmDeleteReservoir(Reservoir reservoir) async {
    final first = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Excluir reservatório?'),
        content: Text('Você está prestes a excluir “${reservoir.name}”. Esta ação removerá a caixa do cadastro desta empresa.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancelar')),
          FilledButton.tonal(onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Sim, continuar')),
        ],
      ),
    );
    if (first != true || !mounted) return;

    int seconds = 5;
    bool ready = false;
    Timer? timer;
    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            if (timer == null) {
              timer = Timer.periodic(const Duration(seconds: 1), (_) {
                if (seconds <= 1) {
                  timer?.cancel();
                  setDialogState(() { seconds = 0; ready = true; });
                } else {
                  setDialogState(() => seconds--);
                }
              });
            }
            return AlertDialog(
              title: const Text('Confirmação final'),
              content: Text(ready
                  ? 'Agora confirme para excluir definitivamente “${reservoir.name}”.'
                  : 'Aguarde $seconds segundos antes de confirmar a exclusão.\n\nEsta segunda etapa existe para evitar exclusões acidentais.'),
              actions: [
                TextButton(onPressed: () { timer?.cancel(); Navigator.pop(dialogContext, false); }, child: const Text('Não excluir')),
                FilledButton(
                  onPressed: ready ? () { timer?.cancel(); Navigator.pop(dialogContext, true); } : null,
                  child: Text(ready ? 'Excluir definitivamente' : 'Aguarde ${seconds}s'),
                ),
              ],
            );
          },
        );
      },
    );

    timer?.cancel();
    if (confirmed == true && mounted) {
      setState(() => widget.company.reservoirs.remove(reservoir));
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Reservatório excluído do cadastro.')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Row(
          children: [
            CompanyAvatar(company: widget.company, radius: 20),
            const SizedBox(width: 10),
            Text(widget.company.name),
          ],
        ),
        actions: [
          IconButton(
            tooltip: 'Editar empresa',
            onPressed: () async {
              final updated = await showDialog<Company>(
                context: context,
                builder: (_) => CompanyEditorDialog(
                  company: widget.company,
                ),
              );
              if (updated != null) {
                widget.company.name = updated.name;
                widget.company.contact = updated.contact;
                widget.company.phone = updated.phone;
                widget.company.location = updated.location;
                widget.company.plan = updated.plan;
                widget.company.logoUrl = updated.logoUrl;
                widget.company.color = updated.color;
                setState(() {});
              }
            },
            icon: const Icon(Icons.edit_outlined),
          ),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Card(
            child: Padding(
              padding: const EdgeInsets.all(18),
              child: Row(
                children: [
                  CompanyAvatar(company: widget.company, radius: 38),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          widget.company.name,
                          style: const TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                        Text(widget.company.location),
                        Text('Plano: ${widget.company.plan.label}'),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 14),
          Card(
            child: Column(
              children: [
                ListTile(
                  title: const Text(
                    'Responsáveis',
                    style: TextStyle(fontWeight: FontWeight.bold),
                  ),
                  trailing: IconButton(
                    onPressed: addContact,
                    icon: const Icon(Icons.person_add_alt_1),
                  ),
                ),
                ...{
                  widget.company.contact,
                  ...widget.company.contacts,
                }.map(
                  (name) => ListTile(
                    leading: const Icon(Icons.person_outline),
                    title: Text(name),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 14),
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Caixas d’água',
                  style: TextStyle(fontSize: 21, fontWeight: FontWeight.bold),
                ),
              ),
              FilledButton.icon(
                onPressed: addReservoir,
                icon: const Icon(Icons.add),
                label: const Text('Adicionar caixa'),
              ),
            ],
          ),
          const SizedBox(height: 8),
          ...widget.company.reservoirs.map(
            (r) => Card(
              child: ListTile(
                title: Text(r.name),
                subtitle: Text(
                  '${r.liters} L • ${r.type} • ${r.location}',
                ),
                trailing: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    StatusBadge(status: r.status),
                    IconButton(
                      tooltip: 'Gerenciar análises por data',
                      onPressed: () => manageAnalyses(r),
                      icon: const Icon(Icons.fact_check_outlined),
                    ),
                    IconButton(
                      tooltip: 'Editar',
                      onPressed: () => editReservoir(r),
                      icon: const Icon(Icons.edit_outlined),
                    ),
                    IconButton(
                      tooltip: 'Excluir caixa',
                      onPressed: () => confirmDeleteReservoir(r),
                      icon: const Icon(Icons.delete_outline),
                    ),
                  ],
                ),
                onTap: () => Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => ReservoirDetailPage(reservoir: r),
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _AnalysisManagementDialog extends StatefulWidget {
  final Reservoir reservoir;
  const _AnalysisManagementDialog({required this.reservoir});

  @override
  State<_AnalysisManagementDialog> createState() => _AnalysisManagementDialogState();
}

class _AnalysisManagementDialogState extends State<_AnalysisManagementDialog> {
  String dayKey(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  String displayDate(DateTime d) => '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';

  Future<void> deleteDate(DateTime date) async {
    final reasonController = TextEditingController();
    final reason = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Excluir análises de ${displayDate(date)}?'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Esta ação remove as análises dessa data do histórico do cliente. O sistema manterá um registro digital da exclusão.'),
            const SizedBox(height: 14),
            TextField(
              controller: reasonController,
              maxLines: 3,
              decoration: const InputDecoration(
                labelText: 'Motivo obrigatório',
                hintText: 'Ex.: dados enviados incorretamente pelo equipamento',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancelar')),
          FilledButton.tonal(
            onPressed: () {
              final value = reasonController.text.trim();
              if (value.isEmpty) return;
              Navigator.pop(ctx, value);
            },
            child: const Text('Continuar'),
          ),
        ],
      ),
    );
    reasonController.dispose();
    if (reason == null || reason.trim().isEmpty || !mounted) return;

    final confirm = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Confirmação final da exclusão'),
        content: Text('Confirme a exclusão das análises de ${displayDate(date)}.\n\nMotivo: $reason\n\nO cliente será informado e a data permanecerá identificada no laudo por uma verificação digital.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancelar')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Excluir análises')),
        ],
      ),
    );
    if (confirm != true || !mounted) return;

    final deletedAt = DateTime.now();
    final code = digitalVerificationCode(date, reason);
    widget.reservoir.history.removeWhere((r) => dayKey(r.date) == dayKey(date));
    widget.reservoir.deletedAnalyses.removeWhere((d) => dayKey(d.date) == dayKey(date));
    widget.reservoir.deletedAnalyses.add(
      DeletedAnalysisRecord(
        date: DateTime(date.year, date.month, date.day),
        reason: reason,
        deletedAt: deletedAt,
        deletedBy: 'Administrador',
        verificationCode: code,
      ),
    );

    final company = companies.firstWhere(
      (c) => c.reservoirs.contains(widget.reservoir),
      orElse: () => companies.first,
    );
    demoNotifications.insert(
      0,
      AppNotification(
        title: 'Análise excluída — ${widget.reservoir.name}',
        message: 'As análises de ${displayDate(date)} foram apagadas pelo administrador. Toque para consultar o registro e o motivo informado.',
        date: deletedAt,
        companyId: company.id,
        reservoirId: widget.reservoir.id,
        analysisDate: DateTime(date.year, date.month, date.day),
      ),
    );

    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Análises de ${displayDate(date)} excluídas. Código: $code')),
    );
  }

  @override
  Widget build(BuildContext context) {
    final groups = <String, List<HistoryRecord>>{};
    for (final record in widget.reservoir.history) {
      groups.putIfAbsent(dayKey(record.date), () => []).add(record);
    }
    final deletedOnly = widget.reservoir.deletedAnalyses.where((d) => !groups.containsKey(dayKey(d.date))).toList();
    for (final d in deletedOnly) {
      groups[dayKey(d.date)] = <HistoryRecord>[];
    }
    final entries = groups.entries.toList()..sort((a, b) => b.key.compareTo(a.key));

    return AlertDialog(
      title: Text('Análises • ${widget.reservoir.name}'),
      content: SizedBox(
        width: 560,
        child: entries.isEmpty
            ? const Padding(
                padding: EdgeInsets.symmetric(vertical: 24),
                child: Text('Não existem análises disponíveis para exclusão.'),
              )
            : ListView.builder(
                shrinkWrap: true,
                itemCount: entries.length,
                itemBuilder: (context, index) {
                  final records = entries[index].value;
                  final deletedRecord = widget.reservoir.deletedAnalyses.where((x) => dayKey(x.date) == entries[index].key).isEmpty ? null : widget.reservoir.deletedAnalyses.where((x) => dayKey(x.date) == entries[index].key).first;
                  final d = records.isNotEmpty ? records.first.date : deletedRecord!.date;
                  final deleted = deletedRecord != null;
                  return Card(
                    child: ListTile(
                      leading: CircleAvatar(child: Text(records.isEmpty ? '—' : '${records.length}')),
                      title: Text(displayDate(d)),
                      subtitle: Text(deleted ? 'Excluída • ${deletedRecord.reason}' : '${records.map((r) => r.point).toSet().join(', ')} • ${records.map((r) => r.status).toSet().join(' / ')}'),
                      trailing: deleted
                          ? const Chip(label: Text('Excluída'))
                          : IconButton(
                              tooltip: 'Excluir análises desta data',
                              onPressed: () => deleteDate(d),
                              icon: const Icon(Icons.delete_outline),
                            ),
                    ),
                  );
                },
              ),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('Fechar')),
      ],
    );
  }
}

