    name = TextEditingController(text: r?.name ?? '');
    location = TextEditingController(text: r?.location ?? '');
    liters = TextEditingController(text: '${r?.liters ?? 5000}');
    type = TextEditingController(text: r?.type ?? 'Polietileno');
    lat = TextEditingController(text: '${r?.latitude ?? -21.76}');
    lon = TextEditingController(text: '${r?.longitude ?? -43.35}');
