  Widget build(BuildContext context) {
    return AlertDialog(
      title: Text(
        widget.reservoir == null ? 'Adicionar caixa' : 'Editar caixa',
      ),
      content: SingleChildScrollView(
        child: SizedBox(
          width: 460,
          child: Column(
            children: [
              TextField(
                controller: name,
                decoration: const InputDecoration(labelText: 'Nome da caixa'),
              ),
              TextField(
                controller: location,
                decoration: const InputDecoration(labelText: 'Local'),
              ),
              TextField(
                controller: liters,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(labelText: 'Capacidade (L)'),
              ),
              TextField(
                controller: type,
                decoration: const InputDecoration(labelText: 'Material/tipo'),
              ),
              Row(
                children: [
                  Expanded(
                    child: TextField(
                      controller: lat,
                      decoration: const InputDecoration(labelText: 'Latitude'),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: TextField(
                      controller: lon,
                      decoration: const InputDecoration(labelText: 'Longitude'),
                    ),
                  ),
                ],
              ),
              if (widget.reservoir == null)
                const Padding(
                  padding: EdgeInsets.only(top: 16),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text(
                      'Nenhum parâmetro pode ser informado manualmente. As análises aparecerão somente depois que o equipamento realizar a medição e enviar os dados ao sistema.',
                      style: TextStyle(color: Colors.grey, fontSize: 12),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancelar'),
        ),
        FilledButton(
          onPressed: () {
            final original = widget.reservoir;
            final r = Reservoir(
              id: original?.id ??
                  'RES-${DateTime.now().millisecondsSinceEpoch}',
              name: name.text.trim().isEmpty ? 'Nova caixa' : name.text,
              location: location.text,
              liters: int.tryParse(liters.text) ?? 5000,
              type: type.text.isEmpty ? 'Polietileno' : type.text,
              ph: original?.ph ?? 0,
              turbidity: original?.turbidity ?? 0,
              tds: original?.tds ?? 0,
              status: original?.status ?? 'Aguardando análise',
              latitude:
                  double.tryParse(lat.text.replaceAll(',', '.')) ?? -21.76,
              longitude:
                  double.tryParse(lon.text.replaceAll(',', '.')) ?? -43.35,
              lastUpdate: original?.lastUpdate ?? DateTime.now(),
              points: original?.points,
              history: original?.history,
              deletedAnalyses: original?.deletedAnalyses,
              seedDemoHistory: original != null,
            );
            Navigator.pop(context, r);
          },
          child: const Text('Salvar'),
        ),
      ],
    );
  }
}

