class OsmMapWidget extends StatefulWidget {
  final List<Company> companies;
  final Reservoir? focusedReservoir;
  final Reservoir? reservoirFilter;
  final bool showCompanyFilters;
  final bool showMapOverlay;
  final bool attentionOnly;
  final int recenterToken;
  final void Function(Reservoir reservoir)? onReservoirTap;

  const OsmMapWidget({
    super.key,
    required this.companies,
    this.focusedReservoir,
    this.reservoirFilter,
    this.showCompanyFilters = true,
    this.showMapOverlay = true,
    this.attentionOnly = false,
    this.recenterToken = 0,
    this.onReservoirTap,
  });

  @override
  State<OsmMapWidget> createState() => _OsmMapWidgetState();
}

class _OsmMapWidgetState extends State<OsmMapWidget> {
  int zoom = 14;
  late double centerLat;
  late double centerLon;
  final Map<String, bool> visible = {};
  final TransformationController _mapController = TransformationController();
  Size? _viewportSize;
  bool _centerPending = true;
  static const double _canvasSize = 2048.0;

  @override
  void initState() {
    super.initState();
    _setCenter(widget.focusedReservoir);
    for (final c in widget.companies) {
      visible[c.id] = true;
    }
  }

  @override
  void didUpdateWidget(covariant OsmMapWidget oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.focusedReservoir?.id != widget.focusedReservoir?.id ||
        oldWidget.recenterToken != widget.recenterToken) {
      _setCenter(widget.focusedReservoir);
      zoom = widget.focusedReservoir == null ? 14 : 16;
      _centerPending = true;
      _centerMapInViewport();
    }
  }

  void _setCenter(Reservoir? reservoir) {
    final all = widget.companies.expand((c) => c.reservoirs).toList();
    if (reservoir != null) {
      centerLat = reservoir.latitude;
      centerLon = reservoir.longitude;
      return;
    }
    if (all.isNotEmpty) {
      centerLat = all.map((r) => r.latitude).reduce((a, b) => a + b) / all.length;
      centerLon = all.map((r) => r.longitude).reduce((a, b) => a + b) / all.length;
      return;
    }
    centerLat = -21.765;
    centerLon = -43.350;
  }

  void _recenter() {
    _setCenter(widget.focusedReservoir);
    zoom = widget.focusedReservoir == null ? 14 : 16;
    _centerPending = true;
    _centerMapInViewport();
    setState(() {});
  }

  void _centerMapInViewport() {
    final size = _viewportSize;
    if (size == null || size.width <= 0 || size.height <= 0) return;
    _mapController.value = Matrix4.identity()
      ..translate(
        (size.width - _canvasSize) / 2,
        (size.height - _canvasSize) / 2,
      );
    _centerPending = false;
  }

  @override
  void dispose() {
    _mapController.dispose();
    super.dispose();
  }

  double worldSize() => 256 * math.pow(2, zoom).toDouble();

  Offset project(double lat, double lon) {
    final size = worldSize();
    final x = (lon + 180) / 360 * size;
    final safeLat = lat.clamp(-85.0511, 85.0511).toDouble();
    final sinLat = math.sin(safeLat * math.pi / 180);
    final y = (0.5 - math.log((1 + sinLat) / (1 - sinLat)) / (4 * math.pi)) * size;
    return Offset(x, y);
  }

  @override
  Widget build(BuildContext context) {
    final center = project(centerLat, centerLon);
    const canvasSize = _canvasSize;
    final offset = Offset(canvasSize / 2 - center.dx, canvasSize / 2 - center.dy);
    final tileCount = math.pow(2, zoom).toInt();
    final centerTileX = center.dx / 256;
    final centerTileY = center.dy / 256;
    final tiles = <Widget>[];

    for (int tx = -5; tx <= 5; tx++) {
      for (int ty = -5; ty <= 5; ty++) {
        final x = centerTileX.floor() + tx;
        final y = centerTileY.floor() + ty;
        if (x < 0 || x >= tileCount || y < 0 || y >= tileCount) continue;
        tiles.add(
          Positioned(
            left: x * 256 + offset.dx,
            top: y * 256 + offset.dy,
            width: 256,
            height: 256,
            child: _ReliableMapTile(z: zoom, x: x, y: y),
          ),
        );
      }
    }

    final markers = <Widget>[];
    for (final company in widget.companies) {
      if (visible[company.id] != true) continue;
      for (final r in company.reservoirs) {
        if (widget.reservoirFilter != null && r.id != widget.reservoirFilter!.id) continue;
        if (widget.attentionOnly && r.status == 'Limpa') continue;
        final p = project(r.latitude, r.longitude);
        markers.add(
          Positioned(
            left: p.dx + offset.dx,
            top: p.dy + offset.dy,
            child: FractionalTranslation(
              translation: const Offset(-0.5, -0.5),
              child: Tooltip(
              message: '${company.name}\n${r.name}',
              child: InkWell(
                borderRadius: BorderRadius.circular(30),
                onTap: () => widget.onReservoirTap?.call(r),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    AnimatedContainer(
                  duration: const Duration(milliseconds: 180),
                  width: widget.focusedReservoir?.id == r.id ? 48 : 40,
                  height: widget.focusedReservoir?.id == r.id ? 48 : 40,
                  decoration: BoxDecoration(
                    color: r.status == 'Limpa' ? statusColor(r.status) : Colors.red,
                    shape: BoxShape.circle,
                    border: Border.all(color: company.color, width: 4),
                    boxShadow: const [BoxShadow(blurRadius: 6, color: Colors.black38)],
                  ),
                  child: const Icon(Icons.water_drop, color: Colors.white, size: 20),
                    ),
                    const SizedBox(height: 3),
                    Container(
                      constraints: const BoxConstraints(maxWidth: 150),
                      padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                      decoration: BoxDecoration(
                        color: Theme.of(context).colorScheme.surface.withValues(alpha: .94),
                        borderRadius: BorderRadius.circular(8),
                        boxShadow: const [BoxShadow(blurRadius: 5, color: Colors.black26)],
                      ),
                      child: Text(
                        r.name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w800),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
          ),
        );
      }
    }

    return Stack(
      fit: StackFit.expand,
      children: [
        Container(color: const Color(0xFFE9EEF0)),
        ClipRect(
          child: LayoutBuilder(
            builder: (context, constraints) {
              final viewport = Size(
                constraints.maxWidth.isFinite ? constraints.maxWidth : 0,
                constraints.maxHeight.isFinite ? constraints.maxHeight : 0,
              );

              if (_viewportSize != viewport) {
                _viewportSize = viewport;
                _centerPending = true;
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (!mounted || !_centerPending) return;
                  _centerMapInViewport();
                });
              } else if (_centerPending) {
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (!mounted || !_centerPending) return;
                  _centerMapInViewport();
                });
              }

              return InteractiveViewer(
                transformationController: _mapController,
                // Mantém o arraste e o pinch de dois dedos no celular,
                // mas impede que a rolagem do mouse/trackpad altere o zoom.
                panEnabled: true,
                scaleEnabled: true,
                trackpadScrollCausesScale: false,
                minScale: .65,
                maxScale: 4,
                boundaryMargin: const EdgeInsets.all(1000),
                constrained: false,
                alignment: Alignment.topLeft,
                child: SizedBox(
                  width: canvasSize,
                  height: canvasSize,
                  child: Stack(children: [...tiles, ...markers]),
                ),
              );
            },
          ),
        ),
        if (widget.showMapOverlay)
          Positioned(
            left: 10,
            top: 10,
            right: 10,
            child: Card(
            color: Theme.of(context).colorScheme.surface.withValues(alpha: .95),
            child: Padding(
              padding: const EdgeInsets.all(8),
              child: Wrap(
                spacing: 7,
                runSpacing: 5,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  const Icon(Icons.layers_outlined, size: 18),
                  if (widget.showCompanyFilters) ...widget.companies.map((c) => FilterChip(
                    avatar: CompanyAvatar(company: c, radius: 9),
                    label: Text(c.name),
                    selected: visible[c.id] == true,
                    onSelected: (v) => setState(() => visible[c.id] = v),
                  )),
                  if (widget.attentionOnly) const Chip(avatar: Icon(Icons.warning, size: 16), label: Text('Somente atenção')),
                  if (widget.reservoirFilter != null) Chip(avatar: const Icon(Icons.water_drop, size: 16), label: Text(widget.reservoirFilter!.name)),
                ],
              ),
            ),
          ),
        ),
        Positioned(
          right: 10,
          bottom: 10,
          child: Card(
            child: Column(
              children: [
                IconButton(
                  tooltip: 'Recentrar no reservatório',
                  onPressed: _recenter,
                  icon: const Icon(Icons.my_location_outlined),
                ),
                IconButton(
                  tooltip: 'Aumentar zoom',
                  onPressed: () => setState(() {
                    zoom = math.min(18, zoom + 1);
                    _centerPending = true;
                    _centerMapInViewport();
                  }),
                  icon: const Icon(Icons.add),
                ),
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  child: Text('z$zoom', style: const TextStyle(fontSize: 11, fontWeight: FontWeight.bold)),
                ),
                IconButton(
                  tooltip: 'Diminuir zoom',
                  onPressed: () => setState(() {
                    zoom = math.max(5, zoom - 1);
                    _centerPending = true;
                    _centerMapInViewport();
                  }),
                  icon: const Icon(Icons.remove),
                ),
              ],
            ),
          ),
        ),
        const Positioned(
          left: 10,
          bottom: 8,
          child: Card(
            child: Padding(
              padding: EdgeInsets.symmetric(horizontal: 7, vertical: 4),
              child: Text('Mapa base • Esri / Carto / OSM', style: TextStyle(fontSize: 9)),
            ),
          ),
        ),
      ],
    );
  }
}

class _ReliableMapTile extends StatelessWidget {
  final int z;
  final int x;
  final int y;

  const _ReliableMapTile({required this.z, required this.x, required this.y});

  Widget tile(String url, Widget fallback) => Image.network(
    url,
    fit: BoxFit.cover,
    gaplessPlayback: true,
    filterQuality: FilterQuality.low,
    loadingBuilder: (context, child, progress) => progress == null ? child : fallback,
    errorBuilder: (_, __, ___) => fallback,
  );

  @override
  Widget build(BuildContext context) {
    final finalFallback = Container(
      decoration: BoxDecoration(
        color: const Color(0xFFE7ECE8),
        border: Border.all(color: const Color(0xFFD5DDD8)),
      ),
      child: CustomPaint(painter: _MapFallbackPainter()),
    );

    final osmFallback = tile(
      'https://tile.openstreetmap.org/$z/$x/$y.png',
      finalFallback,
    );
    final cartoFallback = tile(
      'https://basemaps.cartocdn.com/light_all/$z/$x/$y.png',
      osmFallback,
    );
    return tile(
      'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/$z/$y/$x',
      cartoFallback,
    );
  }
}

class _MapFallbackPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final road = Paint()
      ..color = const Color(0xFFD2D6D3)
      ..strokeWidth = 4;
    final road2 = Paint()
      ..color = const Color(0xFFFAFBFA)
      ..strokeWidth = 1.5;
    for (double i = -size.height; i < size.width + size.height; i += 46) {
      canvas.drawLine(Offset(i, 0), Offset(i - size.height, size.height), road);
      canvas.drawLine(Offset(i, 0), Offset(i - size.height, size.height), road2);
    }
    for (double y = 20; y < size.height; y += 65) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y + 35), road);
      canvas.drawLine(Offset(0, y), Offset(size.width, y + 35), road2);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

