class AdminMessagesPage extends StatefulWidget { const AdminMessagesPage({super.key}); @override State<AdminMessagesPage> createState()=>_AdminMessagesPageState(); }
class _AdminMessagesPageState extends State<AdminMessagesPage>{
  Company? selectedCompany; Reservoir? selectedReservoir; final controller=TextEditingController();
  @override void dispose(){controller.dispose();super.dispose();}
  void send(){
    if(selectedCompany==null || controller.text.trim().isEmpty)return;
    demoNotifications.insert(0,AppNotification(
      title:'Mensagem da administração',
      message:controller.text.trim(),
      date:DateTime.now(),
      companyId:selectedCompany!.id,
      reservoirId:selectedReservoir?.id ?? '',
    ));
    controller.clear();
    setState((){});
  }
  @override Widget build(BuildContext context){final messages=selectedCompany==null?const <AppNotification>[]:demoNotifications.where((n)=>n.companyId==selectedCompany!.id).toList().reversed.toList();return ListView(padding:const EdgeInsets.all(20),children:[
    Row(children:[IconButton(tooltip:'Voltar',onPressed:()=>Navigator.maybePop(context),icon:const Icon(Icons.arrow_back)),const Expanded(child:Text('Mensagens',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)))]),
    DropdownButtonFormField<Company>(initialValue:selectedCompany,decoration:const InputDecoration(labelText:'Empresa',border:OutlineInputBorder()),items:companies.map((c)=>DropdownMenuItem(value:c,child:Text(c.name))).toList(),onChanged:(v)=>setState(() { selectedCompany=v; selectedReservoir=null; })),
    if(selectedCompany!=null) ...[const SizedBox(height:10),DropdownButtonFormField<Reservoir>(initialValue:selectedReservoir,decoration:const InputDecoration(labelText:'Caixa relacionada (opcional)',border:OutlineInputBorder()),items:selectedCompany!.reservoirs.map((r)=>DropdownMenuItem(value:r,child:Text(r.name))).toList(),onChanged:(v)=>setState(()=>selectedReservoir=v)),const SizedBox(height:14),
      Container(height:330,padding:const EdgeInsets.all(12),decoration:BoxDecoration(border:Border.all(color:Theme.of(context).dividerColor),borderRadius:BorderRadius.circular(14)),child:ListView(children:[if(messages.isEmpty) const Center(child:Padding(padding:EdgeInsets.all(40),child:Text('Nenhuma mensagem enviada para esta empresa.'))),...messages.map((n)=>Align(alignment:Alignment.centerRight,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.all(12),constraints:const BoxConstraints(maxWidth:650),decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Text(n.message),Text('${n.date.day.toString().padLeft(2,'0')}/${n.date.month.toString().padLeft(2,'0')} ${n.date.hour.toString().padLeft(2,'0')}:${n.date.minute.toString().padLeft(2,'0')}',style:const TextStyle(fontSize:10,color:Colors.grey))]))))]),),
      const SizedBox(height:10),Row(crossAxisAlignment:CrossAxisAlignment.end,children:[Expanded(child:TextField(controller:controller,minLines:1,maxLines:4,decoration:const InputDecoration(hintText:'Digite a mensagem...',border:OutlineInputBorder()))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send))]),
    ],
  ]);}
