const String _referenceBase64 = '';

// ============================================================
// VISUAL DA CAIXA
// ============================================================

class Tank3D extends StatefulWidget {
  final Reservoir reservoir;
  final String point;
  final bool showValues;
  final int? activeParameter;

  const Tank3D({
    super.key,
    required this.reservoir,
    required this.point,
    required this.showValues,
    this.activeParameter,
  });

  @override
  State<Tank3D> createState() => _Tank3DState();
}

class _Tank3DState extends State<Tank3D> {
  static final Uint8List _referenceBytes = base64Decode(_referenceBase64);

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth.isFinite ? constraints.maxWidth : 800.0;
        final height = constraints.maxHeight.isFinite ? constraints.maxHeight : 520.0;
        const imageRatio = 875 / 600;
        final imageWidth = math.min(width, height * imageRatio);
        final imageHeight = imageWidth / imageRatio;

        return Center(
          child: SizedBox(
            width: imageWidth,
            height: imageHeight,
            child: Stack(
              fit: StackFit.expand,
              children: [
                Image.memory(
                  _referenceBytes,
                  fit: BoxFit.fill,
                  filterQuality: FilterQuality.high,
                  gaplessPlayback: true,
                ),
                _SelectedTankPoint(point: widget.point),
              ],
            ),
          ),
        );
      },
    );
  }
}

class _SelectedTankPoint extends StatelessWidget {
  final String point;

  const _SelectedTankPoint({required this.point});

  Color _color() {
    switch (point) {
      case 'P2':
        return const Color(0xFF16C79A);
      case 'P3':
        return const Color(0xFFFFA000);
      default:
        return const Color(0xFF18A7FF);
    }
  }

  @override
  Widget build(BuildContext context) {
    // Coordenadas relativas aos quadrados originais da imagem 875x600.
    final top = point == 'P1' ? .345 : point == 'P2' ? .575 : .825;
    return Positioned(
      left: 0,
      right: 0,
      top: 0,
      bottom: 0,
      child: IgnorePointer(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final size = constraints.biggest;
            final x = size.width * .718;
            final y = size.height * top;
            final c = _color();
            return Stack(
              children: [
                Positioned(
                  left: x - 14,
                  top: y - 9,
                  child: Container(
                    width: 28,
                    height: 18,
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: .08),
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(color: c, width: 2),
                      boxShadow: [
                        BoxShadow(
                          color: c.withValues(alpha: .20),
                          blurRadius: 6,
                          spreadRadius: 0.5,
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

class TankPainter extends CustomPainter {
  final int liters;
  final PointReading reading;
  final String point;
  final bool showValues;
  final int? activeParameter;
  final String status;

  TankPainter({
    required this.liters,
    required this.reading,
    required this.point,
    required this.showValues,
    required this.activeParameter,
    required this.status,
  });

  Path _roundedTank(Size size, double left, double top, double right, double bottom) {
    final r = math.min((right - left) * .12, 28.0);
    return Path()
      ..moveTo(left + r, top)
      ..lineTo(right - r, top)
      ..quadraticBezierTo(right, top, right, top + r)
      ..lineTo(right - 8, bottom - r * 1.8)
      ..quadraticBezierTo(right - 10, bottom, right - r * 1.8, bottom)
      ..lineTo(left + r * 1.8, bottom)
      ..quadraticBezierTo(left + 10, bottom, left + 8, bottom - r * 1.8)
      ..lineTo(left, top + r)
      ..quadraticBezierTo(left, top, left + r, top)
      ..close();
  }

  void _text(Canvas canvas, String value, Offset offset, {
    double size = 11,
    Color color = Colors.white,
    FontWeight weight = FontWeight.w600,
    double maxWidth = 180,
    TextAlign align = TextAlign.left,
  }) {
    final tp = TextPainter(
      text: TextSpan(text: value, style: TextStyle(fontSize: size, color: color, fontWeight: weight)),
      textDirection: TextDirection.ltr,
      textAlign: align,
      maxLines: 2,
      ellipsis: '…',
    )..layout(maxWidth: maxWidth);
    tp.paint(canvas, offset);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width;
    final h = size.height;
    if (w <= 10 || h <= 10) return;

    final cx = w * .50;
    final tankW = math.min(w * .88, 470.0);
    final left = cx - tankW / 2;
    final right = cx + tankW / 2;
    final top = h * .13;
    final bottom = h * .90;
    final shellTop = top + h * .12;
    final shellBottom = bottom - h * .06;
    final depth = math.min(32.0, w * .075);
    final cutX = left + tankW * .28;
    final innerLeft = cutX + 8;
    final innerRight = right - 14;
    final innerTop = shellTop + 24;
    final innerBottom = shellBottom - 18;

    // Sombra no chão: dá profundidade mesmo em telas pequenas.
    canvas.drawOval(
      Rect.fromCenter(center: Offset(cx + 8, bottom + 5), width: tankW * .76, height: 25),
      Paint()..color = Colors.black.withValues(alpha: .16),
    );

    // Corpo traseiro em perspectiva.
    final rear = Path()
      ..moveTo(left + depth, shellTop)
      ..lineTo(right - depth, shellTop)
      ..lineTo(right - 2, shellBottom - 20)
      ..quadraticBezierTo(right - 8, shellBottom, right - 44, shellBottom + 2)
      ..lineTo(left + 44, shellBottom + 2)
      ..quadraticBezierTo(left + 8, shellBottom, left + 2, shellBottom - 20)
      ..close();
    canvas.drawPath(
      rear,
      Paint()
        ..shader = const LinearGradient(
          colors: [Color(0xFF178DF1), Color(0xFF0757B9), Color(0xFF043F8F)],
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
        ).createShader(Rect.fromLTWH(left, shellTop, tankW, shellBottom - shellTop)),
    );

    // Parede frontal com recorte: a metade esquerda fica sólida e a direita
    // revela o interior, aproximando a aparência da referência enviada.
    final front = _roundedTank(size, left, shellTop + 4, right, shellBottom);
    canvas.drawPath(
      front,
      Paint()
        ..shader = const LinearGradient(
          colors: [Color(0xFF1597F4), Color(0xFF0876D9), Color(0xFF0559B6)],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ).createShader(Rect.fromLTWH(left, shellTop, tankW, shellBottom - shellTop)),
    );

    // Interior profundo.
    final interior = Path()
      ..moveTo(cutX, innerTop)
      ..lineTo(innerRight, innerTop)
      ..lineTo(innerRight - 10, innerBottom - 5)
      ..quadraticBezierTo(cx + 45, innerBottom + 2, cutX, innerBottom - 8)
      ..close();
    canvas.drawPath(interior, Paint()..color = const Color(0xFF063F83));

    // Volume de água, com transparência e gradiente.
    final waterTop = innerTop + (innerBottom - innerTop) * .23;
    final water = Path()
      ..moveTo(innerLeft, waterTop)
      ..quadraticBezierTo((innerLeft + innerRight) / 2, waterTop - 9, innerRight, waterTop + 1)
      ..lineTo(innerRight - 9, innerBottom - 7)
      ..quadraticBezierTo(cx + 38, innerBottom + 2, innerLeft, innerBottom - 6)
      ..close();
    canvas.drawPath(
      water,
      Paint()
        ..shader = const LinearGradient(
          colors: [Color(0xFF62D9FF), Color(0xFF159BEF), Color(0xFF0566C7)],
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
        ).createShader(Rect.fromLTWH(innerLeft, waterTop, innerRight - innerLeft, innerBottom - waterTop)),
    );

    // Ondas da superfície da água.
    final wave = Paint()
      ..color = Colors.white.withValues(alpha: .68)
      ..strokeWidth = 1.6
      ..style = PaintingStyle.stroke;
    for (int i = 0; i < 3; i++) {
      final y = waterTop + i * 5.0;
      final path = Path()..moveTo(innerLeft + 4, y);
      for (double x = innerLeft + 4; x < innerRight - 4; x += 34) {
        path.quadraticBezierTo(x + 8, y - 3, x + 17, y);
        path.quadraticBezierTo(x + 25, y + 3, x + 34, y);
      }
      canvas.drawPath(path, wave);
    }

    // Brilho interno para reforçar o aspecto plástico/3D.
    final shine = Paint()
      ..shader = LinearGradient(
        colors: [Colors.white.withValues(alpha: .20), Colors.transparent],
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
      ).createShader(Rect.fromLTWH(innerLeft, innerTop, innerRight - innerLeft, innerBottom - innerTop));
    canvas.drawPath(water, shine);

    // Recorte lateral da parede frontal.
    final cutWall = Path()
      ..moveTo(left + 4, shellTop + 8)
      ..lineTo(cutX, shellTop + 20)
      ..lineTo(cutX, shellBottom - 10)
      ..quadraticBezierTo(left + 55, shellBottom - 1, left + 16, shellBottom - 28)
      ..close();
    canvas.drawPath(cutWall, Paint()..color = const Color(0xFF0A79DF).withValues(alpha: .96));

    // Borda clara do corte.
    final rim = Paint()
      ..color = const Color(0xFFD9F4FF)
      ..strokeWidth = math.max(2, w * .008)
      ..style = PaintingStyle.stroke;
    canvas.drawLine(Offset(cutX, shellTop + 18), Offset(cutX, shellBottom - 12), rim);
    canvas.drawPath(
      Path()
        ..moveTo(cutX, shellTop + 18)
        ..lineTo(innerRight, shellTop + 18)
        ..lineTo(innerRight - 10, shellBottom - 5),
      rim,
    );

    // Base inferior em perspectiva.
    final base = Path()
      ..moveTo(left + 32, shellBottom - 2)
      ..quadraticBezierTo(cx, shellBottom + 18, right - 32, shellBottom - 2)
      ..lineTo(right - 44, shellBottom + 11)
      ..quadraticBezierTo(cx, shellBottom + 29, left + 44, shellBottom + 11)
      ..close();
    canvas.drawPath(
      base,
      Paint()
        ..shader = const LinearGradient(
          colors: [Color(0xFF0A6BCE), Color(0xFF03458F)],
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
        ).createShader(Rect.fromLTWH(left, shellBottom, tankW, 28)),
    );

    // Tampa superior com perspectiva.
    final lidTop = top;
    final lidBottom = shellTop + 10;
    final lid = Path()
      ..moveTo(left - 6, lidTop + 18)
      ..quadraticBezierTo(cx, lidTop - 8, right + 6, lidTop + 18)
      ..lineTo(right - 2, lidBottom)
      ..quadraticBezierTo(cx, lidBottom + 10, left + 2, lidBottom)
      ..close();
    canvas.drawPath(
      lid,
      Paint()
        ..shader = const LinearGradient(
          colors: [Color(0xFF43B6FF), Color(0xFF0A79E6), Color(0xFF0755B8)],
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
        ).createShader(Rect.fromLTWH(left, lidTop, tankW, lidBottom - lidTop)),
    );
    final lidOpening = Path()
      ..moveTo(cx - tankW * .18, lidTop + 14)
      ..quadraticBezierTo(cx, lidTop + 2, cx + tankW * .18, lidTop + 14)
      ..lineTo(cx + tankW * .11, lidBottom - 2)
      ..quadraticBezierTo(cx, lidBottom + 3, cx - tankW * .11, lidBottom - 2)
      ..close();
    canvas.drawPath(lidOpening, Paint()..color = const Color(0xFF0454AE));

    // Tubulações laterais.
    final pipe = Paint()
      ..color = const Color(0xFF546E7A)
      ..strokeWidth = math.max(5, w * .018)
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(left - 18, shellTop + (shellBottom - shellTop) * .45), Offset(left + 15, shellTop + (shellBottom - shellTop) * .45), pipe);
    canvas.drawLine(Offset(right - 14, shellTop + (shellBottom - shellTop) * .60), Offset(right + 25, shellTop + (shellBottom - shellTop) * .60), pipe);

    // Sensores P1/P2/P3. A posição permanece proporcional ao volume visual.
    final sensorX = innerLeft + (innerRight - innerLeft) * .66;
    final available = innerBottom - waterTop;
    final ys = [
      waterTop + available * .07,
      waterTop + available * .43,
      waterTop + available * .79,
    ];
    const names = ['P1', 'P2', 'P3'];
    for (int i = 0; i < 3; i++) {
      final active = names[i] == point;
      final y = ys[i];
      final sensorColor = active ? const Color(0xFFFF3B30) : const Color(0xFF17232B);
      final stem = Paint()
        ..color = sensorColor
        ..strokeWidth = active ? 4.5 : 3.2
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(Offset(sensorX, y - 28), Offset(sensorX, y + 1), stem);
      canvas.drawCircle(Offset(sensorX, y + 5), active ? 9 : 6, Paint()..color = sensorColor);
      canvas.drawCircle(Offset(sensorX - 2, y + 2), active ? 3 : 2, Paint()..color = Colors.white.withValues(alpha: .22));

      if (showValues) {
        final bg = RRect.fromRectAndRadius(Rect.fromLTWH(sensorX + 13, y - 9, 34, 24), const Radius.circular(7));
        canvas.drawRRect(bg, Paint()..color = Colors.black.withValues(alpha: .62));
        _text(canvas, names[i], Offset(sensorX + 21, y - 4), size: 11, color: Colors.white, weight: FontWeight.bold, maxWidth: 25);
      }
    }

    // Etiqueta do parâmetro selecionado: aparece no próprio tanque.
    if (showValues) {
      final labels = ['pH', 'Turbidez', 'TDS'];
      final values = [
        reading.ph.toStringAsFixed(2),
        '${reading.turbidity.toStringAsFixed(2)} NTU',
        '${reading.tds.toStringAsFixed(0)} ppm',
      ];
      final idx = (activeParameter ?? 1).clamp(0, 2).toInt();
      final title = '${labels[idx]}  ${values[idx]}';
      final boxW = math.min(170.0, w * .42);
      final boxX = left + 14;
      final boxY = shellBottom - 55;
      final callout = RRect.fromRectAndRadius(Rect.fromLTWH(boxX, boxY, boxW, 38), const Radius.circular(11));
      canvas.drawRRect(callout, Paint()..color = Colors.white.withValues(alpha: .94));
      canvas.drawRRect(callout, Paint()..color = const Color(0xFF087E8B)..style = PaintingStyle.stroke..strokeWidth = 1.5);
      _text(canvas, title, Offset(boxX + 10, boxY + 9), size: 13, color: const Color(0xFF12323A), weight: FontWeight.bold, maxWidth: boxW - 20);
    }

    // Capacidade no canto superior.
    if (showValues) {
      final capacity = '${liters.toString()} L';
      _text(canvas, capacity, Offset(left + 16, lidBottom + 4), size: 10, color: Colors.white.withValues(alpha: .90), weight: FontWeight.bold, maxWidth: 80);
    }
  }

  @override
  bool shouldRepaint(covariant TankPainter oldDelegate) =>
      oldDelegate.point != point ||
      oldDelegate.activeParameter != activeParameter ||
      oldDelegate.reading.turbidity != reading.turbidity ||
      oldDelegate.reading.ph != reading.ph ||
      oldDelegate.reading.tds != reading.tds ||
      oldDelegate.status != status ||
      oldDelegate.liters != liters ||
      oldDelegate.showValues != showValues;
}

